#!/usr/bin/env python3
"""FC3D v1.154: viewer at screen-bottom height and 2500 mm distance.

All optical modes use the new horizontally centred viewer target.
Retains the two-tier P2 pyramid, independent doses and compact output names.

Adds --print-mode pyramid-2-1: two base roads and one upper road, no
smoothing pass. Shadow height and non-overlap use the real (2,1) profile.
This is a complete converter; v1.140 and the v1.141-143 patchers are not required.

Retains the v1.140 smoothing controls and rear markings:

Adds --smooth-xy-speed-mm-s (default 30), converted into coordinated XYZ
feed per emitted slope with Z capped at 30 mm/s. Preserves v1.138 geometry,
doses, embedding and all other motion speeds. Rear legend adds XY speed,
two spaces before revision, and reverses the half-size arrow.
Requires canonical 3dprintv1.179.py.
"""
from __future__ import annotations
import argparse, base64, hashlib, json, math, re, sys, tempfile, types, zipfile, zlib
from pathlib import Path

SCRIPT_VERSION="3dprint_black_mirror_wave_grid_v1.154"
REVISION=145
REAR_VERSION_TEXT="154"
EXPECTED_EMITTER="3dprintv1.179"
EMBEDDED_V106_B64=''
OPTICAL_ENGINE_SOURCE='\nOPTICAL_MODES = ("single-arc", "pyramid-3-2-1", "pyramid-2-1")\nARC_PLACEMENT_ORDER = "inner_to_outer" if OPTICAL_MODE == "single-arc" else "outer_to_inner"\nSPACING_SAMPLE_POLICY = "arc_midpoint"\nARC_PROFILE_WIDTH_MM = 0.400\nPROFILE_SAMPLE_COUNT = 25 if OPTICAL_MODE == "single-arc" else 49\nRAY_NUMERICAL_MARGIN = 1.0e-5\nPHYSICAL_TOL_MM = 0.0005\nPHYSICAL_LAYER_HEIGHT_MM = LAYER_HEIGHT_MM * PHYSICAL_HEIGHT_SCALE\nMIN_EMITTED_CHORD_MM = 0.800\n_OPTICAL_LATTICE_CACHE = globals().get("_OPTICAL_LATTICE_CACHE", {})\n\nA_MAIN_NOMINAL_HEIGHT_MM = PHYSICAL_LAYER_HEIGHT_MM\nA_MAIN_E_PER_MM = 0.1567 * LAYER_HEIGHT_MM\nSTRUCTURAL_E_PER_MM = 0.01567 * (LAYER_H_MM / 0.10)\nNOMINAL_TOP_Z_MM = BASE_TOP_Z_MM + (PHYSICAL_LAYER_HEIGHT_MM if OPTICAL_MODE == "single-arc" else 3.0 * PHYSICAL_LAYER_HEIGHT_MM)\n\n# Compact 5x7 rear glyphs.  v1.154 adds A, P, %, and space.\nLABEL_PIXEL_MM = 2.0\nLABEL_TEXT_Y0_MM = 5.0\nVERSION_TEXT_Y0_MM = 23.0\nPARAMETER_TEXT_Y0_MM = 41.0\nARROW_SHAFT_Y0_MM = 62.0\nARROW_SHAFT_Y1_MM = 88.0\nARROW_HEAD_Y0_MM = 84.0\nARROW_HEAD_Y1_MM = 116.0\nARROW_SHAFT_HALF_W_MM = 4.5\nARROW_HEAD_HALF_W_BASE_MM = 17.0\nREAR_LABEL_ROTATION_DEG = 180\nREAR_ARROW_DIRECTION = "opposite-v133"\nLABEL_GLYPHS = {\n    "0": ("01110","10001","10011","10101","11001","10001","01110"),\n    "1": ("01110","00110","00110","00110","00110","00110","11111"),\n    "2": ("11110","00001","00001","11110","10000","10000","11111"),\n    "3": ("11110","00001","00001","01110","00001","00001","11110"),\n    "4": ("10010","10010","10010","11111","00010","00010","00010"),\n    "5": ("11111","10000","10000","11110","00001","00001","11110"),\n    "6": ("01111","10000","10000","11110","10001","10001","01110"),\n    "7": ("11111","00001","00010","00100","01000","01000","01000"),\n    "8": ("01110","10001","10001","01110","10001","10001","01110"),\n    "9": ("01110","10001","10001","01111","00001","00001","11110"),\n    "-": ("00000","00000","00000","11111","00000","00000","00000"),\n    "A": ("01110","10001","10001","11111","10001","10001","10001"),\n    "P": ("11110","10001","10001","11110","10000","10000","10000"),\n    "S": ("01111","10000","10000","01110","00001","00001","11110"),\n    "%": ("11001","11010","00100","00100","01000","10110","00110"),\n    " ": ("000","000","000","000","000","000","000"),\n}\n\n\ndef _text_intervals_v154(piece, text, y_local_mm, y0_mm):\n    row=int(math.floor((float(y_local_mm)-float(y0_mm))/LABEL_PIXEL_MM))\n    if not 0 <= row < 7:\n        return []\n    widths=[len(LABEL_GLYPHS[c][0]) for c in text]\n    total_cols=sum(widths)+max(0,len(text)-1)\n    cursor=0.5*(piece.width_mm-total_cols*LABEL_PIXEL_MM)\n    out=[]\n    for ci,ch in enumerate(text):\n        glyph=LABEL_GLYPHS[ch]\n        for col,bit in enumerate(glyph[row]):\n            if bit == "1":\n                out.append((cursor+col*LABEL_PIXEL_MM,cursor+(col+1)*LABEL_PIXEL_MM))\n        cursor += len(glyph[0])*LABEL_PIXEL_MM\n        if ci != len(text)-1:\n            cursor += LABEL_PIXEL_MM\n    return _merge_intervals(out)\n\n\ndef _arrow_intervals_v154(piece, y_local_mm):\n    # Reverse only the arrow inside its existing box.  The complete rear legend\n    # is still rotated 180 degrees below, so the text orientation is unchanged.\n    y=(ARROW_SHAFT_Y0_MM+ARROW_HEAD_Y1_MM)-float(y_local_mm)\n    cx=piece.width_mm/2.0; out=[]\n    if ARROW_SHAFT_Y0_MM <= y <= ARROW_SHAFT_Y1_MM:\n        out.append((cx-ARROW_SHAFT_HALF_W_MM,cx+ARROW_SHAFT_HALF_W_MM))\n    if ARROW_HEAD_Y0_MM <= y <= ARROW_HEAD_Y1_MM:\n        frac=max(0.0,min(1.0,(ARROW_HEAD_Y1_MM-y)/(ARROW_HEAD_Y1_MM-ARROW_HEAD_Y0_MM)))\n        half=ARROW_HEAD_HALF_W_BASE_MM*frac\n        if half > 1e-9: out.append((cx-half,cx+half))\n    return _merge_intervals(out)\n\n\ndef _unrotated_label_intervals(piece, y_local_mm):\n    return _merge_intervals(\n        _text_intervals_v154(piece,piece.name,y_local_mm,LABEL_TEXT_Y0_MM)\n        + _text_intervals_v154(piece,REAR_VERSION_TEXT,y_local_mm,VERSION_TEXT_Y0_MM)\n        + _text_intervals_v154(piece,REAR_PARAMETER_TEXT,y_local_mm,PARAMETER_TEXT_Y0_MM)\n        + _arrow_intervals_v154(piece,y_local_mm)\n    )\n\n\ndef label_intervals_printer_x(piece, y_local_mm):\n    """Rotate card ID, revision, mode/parameters and arrow together by 180 deg."""\n    raw=_unrotated_label_intervals(piece,piece.height_mm-float(y_local_mm))\n    return _merge_intervals((piece.width_mm-b,piece.width_mm-a) for a,b in raw)\n\n\ndef _polyline_length2(points):\n    return sum(math.hypot(b[0]-a[0],b[1]-a[1]) for a,b in zip(points,points[1:]))\n\n\ndef _gcode_xy(point):\n    """The XY point the printer receives after three-decimal G-code output."""\n    return round(float(point[0]),3),round(float(point[1]),3)\n\n\ndef _gcode_chord_length(a, b):\n    ar=_gcode_xy(a); br=_gcode_xy(b)\n    return math.hypot(br[0]-ar[0],br[1]-ar[1])\n\n\ndef _polyline_prefix_for_length(points, wanted_length):\n    """Return the original absolute curve up to an exact arc-length position."""\n    source=[(float(p[0]),float(p[1])) for p in points]\n    if not source:\n        return []\n    remaining=max(0.0,float(wanted_length)); out=[source[0]]\n    for a,b in zip(source,source[1:]):\n        ds=math.hypot(b[0]-a[0],b[1]-a[1])\n        if ds <= 1e-12:\n            continue\n        if remaining >= ds-1e-12:\n            out.append(b); remaining-=ds\n            if remaining <= 1e-12:\n                return out\n            continue\n        t=remaining/ds\n        out.append((a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t))\n        return out\n    return out\n\n\ndef _coalesce_curve_for_emission(points):\n    """Keep absolute source-curve points at >=0.8-mm chords plus the endpoint."""\n    source=[(float(p[0]),float(p[1])) for p in points]\n    if len(source) <= 2:\n        return source\n    emitted=[source[0]]\n    for point in source[1:-1]:\n        if _gcode_chord_length(emitted[-1],point) >= MIN_EMITTED_CHORD_MM:\n            emitted.append(point)\n    if _gcode_xy(source[-1]) == _gcode_xy(emitted[-1]):\n        emitted[-1]=source[-1]\n    elif source[-1] != emitted[-1]:\n        emitted.append(source[-1])\n    return emitted\n\n\ndef _curve_tangent2(points, idx):\n    j=int(idx); a=points[max(0,j-1)]; b=points[min(len(points)-1,j+1)]\n    dx=b[0]-a[0]; dz=b[1]-a[1]; m=math.hypot(dx,dz)\n    if m <= 1e-12: raise RuntimeError("v1.154: degenerate arc tangent")\n    return dx/m,dz/m\n\n\ndef _du_for_frame(frame):\n    theta=max(1e-6,math.radians(frame["facet_tilt_deg"]))\n    return PHYSICAL_LAYER_HEIGHT_MM/max(1e-9,math.tan(theta))\n\n\ndef _stack_cross_section_profile(facet_tilt_deg):\n    theta=max(1e-6,math.radians(float(facet_tilt_deg)))\n    du=PHYSICAL_LAYER_HEIGHT_MM/max(1e-9,math.tan(theta))\n    counts=_mode_profile()["tier_counts"]\n    tiers=[]\n    for tier,count in enumerate(counts):\n        shift=0.0 if OPTICAL_MODE == "single-arc" else tier*du\n        tiers.append({"tier":tier+1,"road_count":count,"base_height_mm":tier*PHYSICAL_LAYER_HEIGHT_MM,\n                      "centres_u_mm":[shift+(i+0.5)*ARC_PROFILE_WIDTH_MM for i in range(count)]})\n    return {"tiers":tiers,"height_mm":len(counts)*PHYSICAL_LAYER_HEIGHT_MM,\n            "base_width_mm":counts[0]*ARC_PROFILE_WIDTH_MM,"du_mm":du}\n\n\ndef _required_visible_profile_fractions(sample_count=None):\n    if VISIBILITY_PERCENT <= 0: return []\n    n=PROFILE_SAMPLE_COUNT if sample_count is None else max(3,int(sample_count))\n    threshold=1.0-VISIBILITY_PERCENT/100.0\n    vals=[i/(n-1) for i in range(n)]\n    return [f for f in vals if f >= threshold-1e-12]\n\n\ndef _profile_samples(center, sample_count=None):\n    """Outer/projector-facing finite-envelope samples, foot to peak.\n\n    For the pyramid this takes max +B extent of the complete active support-road union at\n    each height.  Surface fraction is cumulative length along that envelope.\n    """\n    cx,cz=map(float,center); frame=mirror_frame_global(cx,cz)\n    profile=_stack_cross_section_profile(frame["facet_tilt_deg"])\n    count=PROFILE_SAMPLE_COUNT if sample_count is None else max(3,int(sample_count))\n    total_h=profile["height_mm"]; a=ARC_PROFILE_WIDTH_MM/2.0\n    raw=[]\n    for i in range(count):\n        h=total_h*i/(count-1); candidates=[]\n        for tier in profile["tiers"]:\n            v=h-tier["base_height_mm"]\n            if -1e-12 <= v <= PHYSICAL_LAYER_HEIGHT_MM+1e-12:\n                v=max(0.0,min(PHYSICAL_LAYER_HEIGHT_MM,v))\n                side=a*math.sqrt(max(0.0,1.0-(v/PHYSICAL_LAYER_HEIGHT_MM)**2))\n                candidates.append(max(tier["centres_u_mm"])+side)\n        if not candidates: continue\n        u=max(candidates); x=cx+frame["b_unit"][0]*u; z=cz+frame["b_unit"][1]*u\n        pv=(MASTER_FAN.projector_x_mm-x,MASTER_FAN.projector_z_mm-z,MASTER_FAN.projector_distance_mm-h)\n        pm=math.sqrt(sum(q*q for q in pv))\n        raw.append({"point_mm":(x,z),"height_mm":h,"u_mm":u,\n                    "projector_unit":tuple(q/pm for q in pv),"projector_distance_mm":pm})\n    lengths=[0.0]\n    for a0,b0 in zip(raw,raw[1:]):\n        lengths.append(lengths[-1]+math.sqrt((b0["point_mm"][0]-a0["point_mm"][0])**2+\n                                             (b0["point_mm"][1]-a0["point_mm"][1])**2+\n                                             (b0["height_mm"]-a0["height_mm"])**2))\n    total=max(lengths[-1],1e-12)\n    for rec,d in zip(raw,lengths): rec["profile_fraction"]=d/total\n    return raw\n\n\ndef _previous_roads(previous_center):\n    px,pz=map(float,previous_center); frame=mirror_frame_global(px,pz)\n    profile=_stack_cross_section_profile(frame["facet_tilt_deg"])\n    return frame,[(u,tier["base_height_mm"]) for tier in profile["tiers"] for u in tier["centres_u_mm"]]\n\n\ndef _ray_margin_against_stack(sample, previous_center, prepared=None):\n    px,pz=map(float,previous_center)\n    frame,roads=_previous_roads(previous_center) if prepared is None else prepared\n    bx,bz=frame["b_unit"][0],frame["b_unit"][1]; bm=math.hypot(bx,bz); bx/=bm; bz/=bm\n    x,z=sample["point_mm"]; rx,rz,rh=sample["projector_unit"]\n    q0=(x-px)*bx+(z-pz)*bz; dq=rx*bx+rz*bz; h0=sample["height_mm"]\n    a=ARC_PROFILE_WIDTH_MM/2.0; b=PHYSICAL_LAYER_HEIGHT_MM; best=float("inf")\n    if rh <= 1e-12: raise RuntimeError("v1.154: projector ray does not rise")\n    for road_u,base_h in roads:\n        lo=max(0.0,(base_h-h0)/rh); hi=min(sample["projector_distance_mm"],(base_h+b-h0)/rh)\n        if hi < lo-1e-12: continue\n        v0=h0-base_h\n        aa=(dq/a)**2+(rh/b)**2\n        bb=2.0*((q0-road_u)*dq/(a*a)+v0*rh/(b*b))\n        cc=((q0-road_u)/a)**2+(v0/b)**2-1.0\n        t=max(lo,min(hi,-bb/(2.0*aa)))\n        best=min(best,aa*t*t+bb*t+cc)\n    return best\n\n\ndef _physical_envelope_gap(current, previous):\n    distances=[]\n    for c,p in zip(current,previous): distances.append(math.hypot(c[0]-p[0],c[1]-p[1]))\n    if not distances: return float("-inf")\n    if OPTICAL_MODE == "single-arc":\n        return min(distances)-ARC_PROFILE_WIDTH_MM\n    gaps=[]\n    for c,p,d in zip(current,previous,distances):\n        dc=_du_for_frame(mirror_frame_global(c[0],c[1]))\n        dp=_du_for_frame(mirror_frame_global(p[0],p[1]))\n        for tier, count in enumerate(_mode_profile()["tier_counts"]):\n            gaps.append(d+tier*dc-tier*dp-count*ARC_PROFILE_WIDTH_MM)\n    return min(gaps)\n\n\ndef _full_arc_physical_gap(current, previous, piece):\n    """Minimum finite-envelope gap over every relevant corresponding point."""\n    if len(current) != len(previous):\n        raise RuntimeError("v1.154: corresponding full curves differ")\n    halo=ARC_PROFILE_WIDTH_MM*(max(_mode_profile()["tier_counts"]) if not _mode_profile()["smooth"] else 1.0)\n    indices=[]\n    for i,(c,p) in enumerate(zip(current,previous)):\n        if ((piece.global_x0_mm-halo<=c[0]<=piece.global_x1_mm+halo and\n             piece.global_z0_mm-halo<=c[1]<=piece.global_z1_mm+halo) or\n            (piece.global_x0_mm-halo<=p[0]<=piece.global_x1_mm+halo and\n             piece.global_z0_mm-halo<=p[1]<=piece.global_z1_mm+halo)):\n            indices.append(i)\n    if not indices: return float("inf")\n    return _physical_envelope_gap([current[i] for i in indices],[previous[i] for i in indices])\n\n\ndef _pair_metrics(current, previous, piece, stride=1, profile_sample_count=None):\n    if len(current) != len(previous): raise RuntimeError("v1.154: corresponding traces differ")\n    halo=ROAD_WIDTH_MM\n    eligible=[i for i,p in enumerate(current) if\n              piece.global_x0_mm-halo <= p[0] <= piece.global_x1_mm+halo and\n              piece.global_z0_mm-halo <= p[1] <= piece.global_z1_mm+halo]\n    idxs=([eligible[len(eligible)//2]] if OPTICAL_MODE in ("pyramid-3-2-1", "pyramid-2-1") and eligible\n          else [i for i in eligible if i%max(1,int(stride))==0])\n    if not idxs: return None\n    physical=_physical_envelope_gap([current[i] for i in idxs],[previous[i] for i in idxs])\n    required=_required_visible_profile_fractions(profile_sample_count)\n    margins=[]; critical=[]\n    if required:\n        threshold=required[0]\n        for i in idxs:\n            # A advances away from the projector: the previous road is the\n            # blocker. P advances toward it: the new/current stack blocks the\n            # previously placed outer stack. Test the actually hidden face.\n            visible,blocker=(current[i],previous[i]) if OPTICAL_MODE=="single-arc" else (previous[i],current[i])\n            samples=[s for s in _profile_samples(visible,profile_sample_count)\n                     if s["profile_fraction"] >= threshold-1e-12]\n            prepared=_previous_roads(blocker)\n            vals=[(_ray_margin_against_stack(s,blocker,prepared),s["profile_fraction"]) for s in samples]\n            m,f=min(vals,key=lambda q:q[0]); margins.append(m); critical.append(f)\n    clear=min(margins) if margins else float("inf")\n    return {"physical_gap_min_mm":physical,"visibility_margin_min":clear,\n            "visibility_clear":not margins or clear >= RAY_NUMERICAL_MARGIN,\n            "critical_profile_fraction":min(critical) if critical else None,\n            "sample_count":len(idxs),"profile_sample_count":profile_sample_count or PROFILE_SAMPLE_COUNT}\n\n\ndef _reference_setup(piece):\n    base=get_mirror_wave_lattice(piece)\n    if OPTICAL_MODE in ("pyramid-3-2-1", "pyramid-2-1"):\n        candidates=[]\n        for rec in base["main_a_curves"]:\n            clips=_clip_polyline2_to_piece(rec["points"],piece)\n            if clips:\n                pts=clips[0]; rr=[math.hypot(x-MASTER_FAN.projector_x_mm,z-MASTER_FAN.projector_z_mm) for x,z in pts]\n                candidates.append((sum(rr)/len(rr),rec))\n        if not candidates: raise RuntimeError(f"{piece.name}: no outer reference arc")\n        full=[(float(x),float(z)) for x,z in max(candidates,key=lambda q:q[0])[1]["points"]]\n        halo=0.5*max(piece.width_mm,piece.height_mm)\n        idx=[i for i,(x,z) in enumerate(full) if piece.global_x0_mm-halo<=x<=piece.global_x1_mm+halo and piece.global_z0_mm-halo<=z<=piece.global_z1_mm+halo]\n        a=max(0,min(idx)-2); b=min(len(full),max(idx)+3)\n        return {"curve":_resample_polyline2(full[a:b],1.0),"advance":"curve"}\n    first=base["main_a_local"][0]; wave=first["wave"]; family=first["family"]\n    rec=next(r for r in base["main_a_curves"] if r["wave"]==wave and r["family"]==family)\n    pts=[(float(x),float(z)) for x,z in rec["points"]]\n    pc=(0.5*(piece.global_x0_mm+piece.global_x1_mm),0.5*(piece.global_z0_mm+piece.global_z1_mm))\n    si=min(range(len(pts)),key=lambda i:math.hypot(pts[i][0]-pc[0],pts[i][1]-pc[1]))\n    return {"curve":_trace_a_streamline_global(pts[si][0],pts[si][1],_polyline_length2(pts[:si+1]),_polyline_length2(pts[si:]),A_TRACE_STEP_MM),\n            "advance":"seed","seed":pts[si],"negative":_polyline_length2(pts[:si+1]),"positive":_polyline_length2(pts[si:])}\n\n\ndef _advance_candidate(previous, setup, distance):\n    if setup["advance"] == "curve":\n        return _waveset_advance_curve_inward(previous,distance),None\n    seed,_=_advance_b_rise_global(setup["seed"][0],setup["seed"][1],distance,B_FRONT_MAX_STEP_MM)\n    return _trace_a_streamline_global(seed[0],seed[1],setup["negative"],setup["positive"],A_TRACE_STEP_MM),seed\n\n\ndef _curve_midpoint_in_piece(curve, piece):\n    halo=ROAD_WIDTH_MM\n    eligible=[p for p in curve if piece.global_x0_mm-halo<=p[0]<=piece.global_x1_mm+halo and\n              piece.global_z0_mm-halo<=p[1]<=piece.global_z1_mm+halo]\n    return eligible[len(eligible)//2] if eligible else curve[len(curve)//2]\n\n\ndef _advance_midpoint(point, distance):\n    if OPTICAL_MODE in ("pyramid-3-2-1", "pyramid-2-1"): return _waveset_advance_point_inward(point[0],point[1],distance)\n    return _advance_b_rise_global(point[0],point[1],distance,B_FRONT_MAX_STEP_MM)[0]\n\n\ndef _offset_road_curve(curve, tier, road_index):\n    if OPTICAL_MODE == "single-arc": return list(curve)\n    out=[]\n    for x,z in curve:\n        fr=mirror_frame_global(x,z); du=_du_for_frame(fr)\n        off=tier*du+(road_index+0.5)*ARC_PROFILE_WIDTH_MM\n        out.append((x+fr["b_unit"][0]*off,z+fr["b_unit"][1]*off))\n    return out\n\n\ndef _clip_roads(curve, piece):\n    counts=_mode_profile()["tier_counts"]\n    roads={}\n    for tier,count in enumerate(counts):\n        for ri in range(count):\n            clips=_waveset_clip_curve(_offset_road_curve(curve,tier,ri),piece)\n            roads[(tier,ri)]=[(p[0]-piece.global_x0_mm,p[1]-piece.global_z0_mm) for p in clips]\n    return roads\n\n\ndef generate_optical_lattice(piece):\n    setup=_reference_setup(piece); previous=setup["curve"]\n    plans=[]; seen=False\n    for slot in range(1000):\n        clipped=_clip_roads(previous,piece)\n        printable=all(len(v)>=2 for v in clipped.values())\n        if printable: seen=True\n        elif seen: break\n        plans.append({"slot":slot,"curve":previous,"roads":clipped,"printable":printable,\n                      "seed_pitch_mm":None if slot==0 else plans[-1]["next_pitch_mm"],"metrics":None})\n        previous_mid=_curve_midpoint_in_piece(previous,piece)\n        def candidate(distance, samples=7):\n            current_mid=_advance_midpoint(previous_mid,distance)\n            return current_mid,_pair_metrics([current_mid],[previous_mid],piece,1,samples)\n        low=0.0; high=max(0.45,ARC_PROFILE_WIDTH_MM); finished=False\n        while True:\n            current_mid,metrics=candidate(high)\n            if metrics is None:\n                probe,_=_advance_candidate(previous,setup,high)\n                if not _waveset_clip_curve(probe,piece): finished=True; break\n            if metrics and metrics["physical_gap_min_mm"]>=0.0 and metrics["visibility_clear"]:\n                for _ in range(10):\n                    mid=0.5*(low+high); mc,mm=candidate(mid)\n                    if mm and mm["physical_gap_min_mm"]>=0.0 and mm["visibility_clear"]: high=mid\n                    else: low=mid\n                current_mid,metrics=candidate(high,samples=PROFILE_SAMPLE_COUNT)\n                if not (metrics and metrics["physical_gap_min_mm"]>=0.0 and metrics["visibility_clear"]):\n                    low=high; high*=1.02; continue\n                curve,seed=_advance_candidate(previous,setup,high)\n                full_gap=_full_arc_physical_gap(curve,previous,piece)\n                # Midpoint shadow spacing is allowed to grow, never to undercut\n                # the complete finite-road envelopes. Correct only real overlap.\n                for _ in range(40):\n                    white=_white_full_metrics(curve,previous,piece,256)\n                    white_ok=white is None or white["projector_min"] >= min(1.,VISIBILITY_PERCENT/100+.005)-1e-9\n                    if full_gap>=0.0 and white_ok: break\n                    high += max(0.02,-full_gap + 1.0e-9)\n                    curve,seed=_advance_candidate(previous,setup,high)\n                    full_gap=_full_arc_physical_gap(curve,previous,piece)\n                else:\n                    raise RuntimeError(f"{piece.name}: v1.154 full-arc physical clearance did not converge")\n                if full_gap<0.0:\n                    raise RuntimeError(f"{piece.name}: v1.154 full-arc physical overlap {full_gap:.9f} mm")\n                current_mid,metrics=candidate(high,samples=PROFILE_SAMPLE_COUNT)\n                if not (metrics and metrics["physical_gap_min_mm"]>=0.0 and metrics["visibility_clear"]):\n                    raise RuntimeError(f"{piece.name}: v1.154 corrected pitch lost midpoint clearance")\n                plans[-1]["white_full_metrics"]=white\n                plans[-1]["next_pitch_mm"]=high\n                plans[-1]["next_metrics"]=metrics\n                plans[-1]["next_full_arc_physical_gap_mm"]=full_gap\n                if setup["advance"]=="seed": setup["seed"]=seed\n                previous=curve\n                break\n            high*=1.15\n            if high>8.0: raise RuntimeError(f"{piece.name}: v1.154 spacing solve exceeded 8 mm")\n        if finished: break\n    else: raise RuntimeError(f"{piece.name}: v1.154 lattice exceeded 1000 slots")\n    printable=[p for p in plans if p["printable"]]\n    if len(printable)<2: raise RuntimeError(f"{piece.name}: too few printable optical stacks")\n    return {"piece":piece.name,"mode":OPTICAL_MODE,"visibility_percent":VISIBILITY_PERCENT,\n            "layer_height_mm":LAYER_HEIGHT_MM,"physical_height_scale":PHYSICAL_HEIGHT_SCALE,\n            "physical_layer_height_mm":PHYSICAL_LAYER_HEIGHT_MM,"plans":plans,"printable":printable}\n\n\ndef get_optical_lattice(piece):\n    key=(piece.name,OPTICAL_MODE,LAYER_HEIGHT_MM,PHYSICAL_HEIGHT_SCALE,VISIBILITY_PERCENT)\n    if key not in _OPTICAL_LATTICE_CACHE: _OPTICAL_LATTICE_CACHE[key]=generate_optical_lattice(piece)\n    return _OPTICAL_LATTICE_CACHE[key]\n\n\ndef optical_spacing_report(piece):\n    lat=get_optical_lattice(piece); rec=[p["next_metrics"] for p in lat["plans"] if p.get("next_metrics")]\n    guarded=[p for p in lat["plans"] if p.get("next_metrics")]\n    pitches=[p["next_pitch_mm"] for p in guarded]\n    full_gaps=[p["next_full_arc_physical_gap_mm"] for p in guarded]\n    return {"result":"PASS","mode":OPTICAL_MODE,"visibility_percent":VISIBILITY_PERCENT,\n            "layer_height_mm":LAYER_HEIGHT_MM,"physical_height_scale":PHYSICAL_HEIGHT_SCALE,\n            "physical_layer_height_mm":PHYSICAL_LAYER_HEIGHT_MM,"printable_stacks":len(lat["printable"]),\n            "spacing_sample_policy":SPACING_SAMPLE_POLICY,\n            "pitch_mm":{"min":min(pitches),"mean":sum(pitches)/len(pitches),"max":max(pitches)},\n            "physical_gap_min_mm":min(full_gaps),\n            "midpoint_physical_gap_min_mm":min(r["physical_gap_min_mm"] for r in rec),\n            "visibility_margin_min":min(r["visibility_margin_min"] for r in rec),\n            "full_required_profile_clear":all(r["visibility_clear"] for r in rec)}\n\n\ndef _explicit_mirror_wave_layer_gcode(piece, x_origin, y_origin):\n    lat=get_optical_lattice(piece); xo=float(x_origin); yo=float(y_origin)\n    rows=[f"; FC3D_V1154_OPTICAL_START mode={OPTICAL_MODE} visibility={VISIBILITY_PERCENT}% dose_height={LAYER_HEIGHT_MM:.3f} physical_height_scale={PHYSICAL_HEIGHT_SCALE:.3f} physical_layer_height={PHYSICAL_LAYER_HEIGHT_MM:.3f} stacks={len(lat[\'printable\'])}"]\n    counts=_mode_profile()["tier_counts"]\n    travel_z=BASE_TOP_Z_MM+len(counts)*PHYSICAL_LAYER_HEIGHT_MM+0.160\n    road_no=0\n    for tier,count in enumerate(counts):\n        z_abs=BASE_TOP_Z_MM+(tier+1)*PHYSICAL_LAYER_HEIGHT_MM\n        for stack_no,plan in enumerate(lat["printable"],1):\n            for ri in range(count):\n                pts=[(xo+p[0],yo+p[1]) for p in plan["roads"][(tier,ri)]]\n                seg=[math.hypot(b[0]-a[0],b[1]-a[1]) for a,b in zip(pts,pts[1:])]\n                total=sum(seg); dry=min(0.160,max(0.0,total*0.45)); draw=max(0.0,total-dry)\n                if draw<=1e-8: continue\n                draw_pts=_coalesce_curve_for_emission(_polyline_prefix_for_length(pts,draw))\n                road_no+=1\n                rows.append(f"; FC3D_V1154_OPTICAL_ROAD_START road={road_no} stack={stack_no} tier={tier+1} tier_road={ri+1} z={z_abs:.3f}")\n                rows.append(f"G0 Z{travel_z:.3f} F900 ; FC3D_V1154_OPTICAL_TRAVEL_Z")\n                rows.append(f"G0 X{pts[0][0]:.3f} Y{pts[0][1]:.3f} F18000 ; FC3D_V1154_OPTICAL_MOVE")\n                rows.append(f"G0 Z{z_abs:.3f} F900 ; FC3D_V1154_OPTICAL_HEIGHT")\n                rows.append("G1 E0.795 F1800 ; FC3D_V1154_OPTICAL_REPRIME")\n                for j,(a0,b0) in enumerate(zip(draw_pts,draw_pts[1:])):\n                    ds=_gcode_chord_length(a0,b0)\n                    e=ds*A_MAIN_E_PER_MM\n                    if round(e,5)>0: rows.append(f"G1 X{b0[0]:.3f} Y{b0[1]:.3f} Z{z_abs:.3f} E{e:.5f} F{A_PRINT_FEED_MM_S*60:.0f} ; FC3D_V1154_OPTICAL_SEG road={road_no} seg={j}")\n                rows.append("G1 E-0.800 F1800 ; FC3D_V1154_OPTICAL_RETRACT")\n                if dry>1e-9: rows.append(f"G1 X{pts[-1][0]:.3f} Y{pts[-1][1]:.3f} Z{z_abs:.3f} F15000 ; FC3D_V1154_OPTICAL_DRY_TAIL len={dry:.3f}")\n                rows.append(f"; FC3D_V1154_OPTICAL_ROAD_END road={road_no}")\n    rows.append(f"G0 Z{travel_z:.3f} F900 ; FC3D_V1154_OPTICAL_SAFE_END_Z")\n    rows.append(f"; FC3D_V1154_OPTICAL_END roads={road_no}")\n    return rows\n\n\ndef audit_final_mirror_wave_paths(output):\n    with zipfile.ZipFile(output,"r") as z: g=z.read("Metadata/plate_1.gcode").decode("utf-8")\n    block=g[g.find("FC3D_V1154_OPTICAL_START"):g.find("FC3D_V1154_OPTICAL_END")]\n    roads=block.count("FC3D_V1154_OPTICAL_ROAD_START")\n    if not roads or roads!=block.count("FC3D_V1154_OPTICAL_REPRIME") or roads!=block.count("FC3D_V1154_OPTICAL_RETRACT") or roads!=block.count("FC3D_V1154_OPTICAL_ROAD_END"):\n        raise RuntimeError("v1.154: optical pressure-cycle audit failed")\n    return {"mode":OPTICAL_MODE,"roads":roads,"visibility_percent":VISIBILITY_PERCENT,"layer_height_mm":LAYER_HEIGHT_MM}\n\n\n# v1.154 support-first smooth-mode layer.\nMODE_PROFILES = {\n    "single-arc": {"tier_counts": (1,), "smooth": False, "placement": "inner_to_outer"},\n    "pyramid-3-2-1": {"tier_counts": (3, 2, 1), "smooth": False, "placement": "outer_to_inner"},\n    "pyramid-2-1": {"tier_counts": (2, 1), "smooth": False, "placement": "outer_to_inner"},\n    "smooth1": {"tier_counts": (1,), "smooth": True, "placement": "outer_to_inner"},\n    "smooth2": {"tier_counts": (2, 1), "smooth": True, "placement": "outer_to_inner"},\n    "smooth3": {"tier_counts": (3, 2, 1), "smooth": True, "placement": "outer_to_inner"},\n}\nOPTICAL_MODES = tuple(MODE_PROFILES)\nif not MODE_PROFILES[OPTICAL_MODE]["smooth"]:\n    NOMINAL_TOP_Z_MM = BASE_TOP_Z_MM + len(MODE_PROFILES[OPTICAL_MODE]["tier_counts"]) * PHYSICAL_LAYER_HEIGHT_MM\nARC_PLACEMENT_ORDER = MODE_PROFILES[OPTICAL_MODE]["placement"]\nSMOOTH_LAYER_HEIGHT_MM = float(globals().get("SMOOTH_LAYER_HEIGHT_MM", 0.100))\nSMOOTH_EMBED_DEPTH_MM = float(globals().get("SMOOTH_EMBED_DEPTH_MM", 0.020))\nSMOOTH_REAR_MAX_EMBED_MM = float(globals().get("SMOOTH_REAR_MAX_EMBED_MM", SMOOTH_LAYER_HEIGHT_MM))\nSMOOTH_NOZZLE_FLAT_DIAMETER_MM = globals().get("SMOOTH_NOZZLE_FLAT_DIAMETER_MM")\nSMOOTH_MAX_NOZZLE_PENETRATION_MM = globals().get("SMOOTH_MAX_NOZZLE_PENETRATION_MM")\nSMOOTH_E_PER_MM = 0.1567 * SMOOTH_LAYER_HEIGHT_MM\nSMOOTH_BASE_Z_MM = BASE_TOP_Z_MM + SMOOTH_LAYER_HEIGHT_MM\nSMOOTH_XY_SPEED_MM_S = float(globals().get("SMOOTH_XY_SPEED_MM_S", 30.0))\n# Bambu Studio official A1 mini 0.4 profile: machine_max_speed_z=30.\n# https://github.com/bambulab/BambuStudio/blob/master/resources/profiles/BBL/machine/Bambu%20Lab%20A1%20mini%200.4%20nozzle.json\n# This caps commanded axis velocity; firmware still plans acceleration/junctions.\nSMOOTH_Z_SPEED_LIMIT_MM_S = 30.0\nREAR_ARROW_DIRECTION = "opposite-v138"\nLABEL_PIXEL_MM = 1.8\nLABEL_SPACE_MM = 0.0\nARROW_SHAFT_HALF_W_MM = 2.25\nARROW_HEAD_HALF_W_BASE_MM = 8.5\nARROW_SHAFT_Y0_MM = 75.5\nARROW_SHAFT_Y1_MM = 88.5\nARROW_HEAD_Y0_MM = 86.5\nARROW_HEAD_Y1_MM = 102.5\nLABEL_GLYPHS.update({\n    "X": ("10001","10001","01010","00100","01010","10001","10001"),\n    "Y": ("10001","10001","01010","00100","00100","00100","00100"),\n    ".": ("00","00","00","00","00","11","11"),\n    "D": ("11110","10001","10001","10001","10001","10001","11110"),\n    "E": ("11111","10000","10000","11110","10000","10000","11111"),\n    "H": ("10001","10001","10001","11111","10001","10001","10001"),\n})\nREAR_TEXT_LINES = tuple(globals().get("REAR_TEXT_LINES") or ("1-1  139", REAR_PARAMETER_TEXT, ""))\nLABEL_LINE_Y0_MM = (5.0, 23.0, 41.0, 59.0)\n\n\ndef _mode_profile():\n    return MODE_PROFILES[OPTICAL_MODE]\n\n\ndef _stack_cross_section_profile(facet_tilt_deg):\n    theta = max(1e-6, math.radians(float(facet_tilt_deg)))\n    du = PHYSICAL_LAYER_HEIGHT_MM / max(1e-9, math.tan(theta))\n    counts = _mode_profile()["tier_counts"]\n    tiers = []\n    for tier, count in enumerate(counts):\n        shift = 0.0 if OPTICAL_MODE == "single-arc" else tier * du\n        tiers.append({\n            "tier": tier + 1,\n            "road_count": count,\n            "base_height_mm": tier * PHYSICAL_LAYER_HEIGHT_MM,\n            "centres_u_mm": [shift + (i + 0.5) * ARC_PROFILE_WIDTH_MM for i in range(count)],\n        })\n    base_centres = tiers[0]["centres_u_mm"]\n    return {\n        "tiers": tiers,\n        "height_mm": len(counts) * PHYSICAL_LAYER_HEIGHT_MM,\n        "base_width_mm": counts[0] * ARC_PROFILE_WIDTH_MM,\n        "du_mm": du,\n        "front_base_edge_u_mm": max(base_centres) + 0.5 * ARC_PROFILE_WIDTH_MM,\n        "rear_base_edge_u_mm": min(base_centres) - 0.5 * ARC_PROFILE_WIDTH_MM,\n    }\n\n\ndef _support_linear_max(profile, gradient, lower=-float(\'inf\'), upper=float(\'inf\')):\n    """Exact max of P(u)+gradient*u on clipped half-ellipse support roads."""\n    a = 0.5 * ARC_PROFILE_WIDTH_MM\n    height = PHYSICAL_LAYER_HEIGHT_MM\n    best, location = -float(\'inf\'), None\n    for tier in profile[\'tiers\']:\n        base = tier[\'base_height_mm\']\n        for center in tier[\'centres_u_mm\']:\n            lo, hi = max(lower, center-a), min(upper, center+a)\n            if hi < lo:\n                continue\n            stationary = center + gradient*a*a / math.hypot(height, gradient*a)\n            u = min(hi, max(lo, stationary))\n            top = base + height*math.sqrt(max(0.0, 1.0-((u-center)/a)**2))\n            value = top + gradient*u\n            if value > best:\n                best, location = value, u\n    return best, location\n\n\ndef _flat_tip_contact_max(profile, slope, intercept, start, end, radius):\n    """Static 2D swept flat-tip estimate; original support, no melt prediction."""\n    lo, hi = min(start,end), max(start,end)\n    if slope > 0:\n        ranges = ((lo-radius,lo+radius,0.0,-slope*lo-intercept),\n                  (lo+radius,hi+radius,-slope,slope*radius-intercept))\n    elif slope < 0:\n        ranges = ((lo-radius,hi-radius,-slope,-slope*radius-intercept),\n                  (hi-radius,hi+radius,0.0,-slope*hi-intercept))\n    else:\n        ranges = ((lo-radius,hi+radius,0.0,-intercept),)\n    return max((_support_linear_max(profile,g,a,b)[0]+k for a,b,g,k in ranges),\n               default=-float(\'inf\'))\n\n\ndef _smooth_cross_section_profile(facet_tilt_deg, support=None):\n    """Fit a fixed optical slope to the immutable support by vertical embedding."""\n    if not _mode_profile()[\'smooth\']:\n        raise ValueError(\'smooth cross-section requested for a non-smooth mode\')\n    angle = float(facet_tilt_deg)\n    if not math.isfinite(angle) or not 0.0 < angle < 89.9:\n        raise ValueError(\'smoothing optical angle must be finite and between 0 and 89.9 degrees\')\n    theta = math.radians(angle)\n    slope = math.tan(theta)\n    profile = _stack_cross_section_profile(angle) if support is None else support\n    leading = max(profile[\'tiers\'][0][\'centres_u_mm\'])\n    crest_u = profile[\'tiers\'][-1][\'centres_u_mm\'][0]\n    h, embed = SMOOTH_LAYER_HEIGHT_MM, SMOOTH_EMBED_DEPTH_MM\n    tangent, touch_u = _support_linear_max(profile,slope,crest_u)\n    intercept = tangent + h - embed\n    crest_h = intercept-slope*crest_u\n    front_u = (intercept-h)/slope\n    if crest_h <= h+1e-9 or front_u <= crest_u+1e-9:\n        raise ValueError(\'smoothing embed depth leaves no rising optical face above the valley\')\n    if OPTICAL_MODE == \'smooth1\':\n        rear_angle = theta\n    else:\n        rear_angle = math.atan2(profile[\'height_mm\'],\n                                abs(crest_u-profile[\'rear_base_edge_u_mm\']))\n    rear_slope = math.tan(rear_angle)\n    rear_u = crest_u-(crest_h-h)/rear_slope\n    rear_intercept = crest_h-rear_slope*crest_u\n    # Clip the tests to the actual printed front and rear legs, including the\n    # level landing if it lies inside the footprint of the rearmost road.\n    front_max = _support_linear_max(profile,slope,crest_u,front_u)[0]-intercept+h\n    if not math.isfinite(front_max) or abs(front_max-embed) > 1e-7:\n        raise ValueError(f\'{OPTICAL_MODE} smoothing embed depth {embed:.6f} mm cannot be achieved \'\n                         \'on the printed front face: the support contact lies beyond the derived foot; \'\n                         \'reduce embedding depth or increase support height\')\n    rear_max = _support_linear_max(profile,-rear_slope,rear_u,crest_u)[0]-rear_intercept+h\n    valley_max = _support_linear_max(profile,0.0,upper=rear_u)[0]\n    rear_max = max(rear_max,valley_max)\n    if rear_max > SMOOTH_REAR_MAX_EMBED_MM+1e-9:\n        raise ValueError(f\'{OPTICAL_MODE} rear smoothing embed {rear_max:.6f} mm exceeds \'\n                         f\'limit {SMOOTH_REAR_MAX_EMBED_MM:.6f} mm at optical angle {angle:.4f}; \'\n                         \'front fit and support/back angle have not been altered\')\n    nozzle_max = None\n    if SMOOTH_NOZZLE_FLAT_DIAMETER_MM is not None:\n        radius = SMOOTH_NOZZLE_FLAT_DIAMETER_MM/2.0\n        front_contact = _flat_tip_contact_max(profile,-slope,intercept,crest_u,front_u,radius)\n        rear_contact = _flat_tip_contact_max(profile,rear_slope,rear_intercept,rear_u,crest_u,radius)\n        # A level valley can still sweep into the rear edge of this assembly.\n        valley_contact = _support_linear_max(profile,0.0,upper=rear_u+radius)[0]-h\n        nozzle_max = max(0.0,front_contact,rear_contact,valley_contact)\n        if (SMOOTH_MAX_NOZZLE_PENETRATION_MM is not None and\n                nozzle_max > SMOOTH_MAX_NOZZLE_PENETRATION_MM+1e-9):\n            raise ValueError(f\'{OPTICAL_MODE} nozzle penetration {nozzle_max:.6f} mm exceeds \'\n                             f\'declared limit {SMOOTH_MAX_NOZZLE_PENETRATION_MM:.6f} mm \'\n                             f\'for flat diameter {SMOOTH_NOZZLE_FLAT_DIAMETER_MM:.3f} mm\')\n    return {\n        \'leading_base_u_mm\':leading,\n        \'front_foot_u_mm\':front_u,\'front_foot_height_mm\':h,\n        \'front_angle_deg\':angle,\'crest_u_mm\':crest_u,\'crest_height_mm\':crest_h,\n        \'rear_angle_deg\':math.degrees(rear_angle),\n        \'rear_foot_u_mm\':rear_u,\'rear_foot_height_mm\':h,\n        \'smooth_layer_height_mm\':h,\'smooth_e_per_mm\':SMOOTH_E_PER_MM,\n        \'smooth_embed_depth_mm\':embed,\'front_embed_max_mm\':front_max,\n        \'rear_embed_max_mm\':rear_max,\'front_touch_u_mm\':touch_u,\n        \'derived_front_distance_mm\':front_u-leading-0.5*ARC_PROFILE_WIDTH_MM,\n        \'nozzle_penetration_max_mm\':nozzle_max,\n        \'support_contact_model\':\'half_ellipse_vertical\',\n    }\n\n\ndef _text_width_mm(text):\n    widths = [0 if c == " " else len(LABEL_GLYPHS[c][0]) for c in text]\n    return (sum(widths) + max(0, len(text) - 1)) * LABEL_PIXEL_MM\n\n\ndef _text_intervals_v154(piece, text, y_local_mm, y0_mm):\n    row = int(math.floor((float(y_local_mm) - float(y0_mm)) / LABEL_PIXEL_MM))\n    if not 0 <= row < 7:\n        return []\n    cursor = 0.5 * (piece.width_mm - _text_width_mm(text))\n    out = []\n    for ci, ch in enumerate(text):\n        glyph = LABEL_GLYPHS[ch]\n        if ch != " ":\n            for col, bit in enumerate(glyph[row]):\n                if bit == "1":\n                    out.append((cursor + col * LABEL_PIXEL_MM, cursor + (col + 1) * LABEL_PIXEL_MM))\n            cursor += len(glyph[0]) * LABEL_PIXEL_MM\n        if ci != len(text) - 1:\n            cursor += LABEL_PIXEL_MM\n    return _merge_intervals(out)\n\n\ndef _unrotated_label_intervals(piece, y_local_mm):\n    text = []\n    for line, y0 in zip(REAR_TEXT_LINES, LABEL_LINE_Y0_MM):\n        if line:\n            text += _text_intervals_v154(piece, line, y_local_mm, y0)\n    return _merge_intervals(text + _arrow_intervals_v154(piece, y_local_mm))\n\n\ndef _arrow_intervals_v154(piece, y_local_mm):\n    """Reverse v1.138\'s half-size arrow; retain the shared legend rotation."""\n    y = ARROW_SHAFT_Y0_MM + ARROW_HEAD_Y1_MM - float(y_local_mm)\n    cx = piece.width_mm / 2.0\n    out = []\n    if ARROW_SHAFT_Y0_MM <= y <= ARROW_SHAFT_Y1_MM:\n        out.append((cx - ARROW_SHAFT_HALF_W_MM, cx + ARROW_SHAFT_HALF_W_MM))\n    if ARROW_HEAD_Y0_MM <= y <= ARROW_HEAD_Y1_MM:\n        frac = max(0.0, min(1.0, (ARROW_HEAD_Y1_MM - y) /\n                                (ARROW_HEAD_Y1_MM - ARROW_HEAD_Y0_MM)))\n        half = ARROW_HEAD_HALF_W_BASE_MM * frac\n        if half > 1e-9:\n            out.append((cx - half, cx + half))\n    return _merge_intervals(out)\n\n\ndef _reference_setup(piece):\n    base = get_mirror_wave_lattice(piece)\n    if _mode_profile()["placement"] == "outer_to_inner":\n        candidates = []\n        for rec in base["main_a_curves"]:\n            clips = _clip_polyline2_to_piece(rec["points"], piece)\n            if clips:\n                pts = clips[0]\n                radii = [math.hypot(x - MASTER_FAN.projector_x_mm,\n                                    z - MASTER_FAN.projector_z_mm) for x, z in pts]\n                candidates.append((sum(radii) / len(radii), rec))\n        if not candidates:\n            raise RuntimeError(f"{piece.name}: no outer reference arc")\n        full = [(float(x), float(z)) for x, z in max(candidates, key=lambda q: q[0])[1]["points"]]\n        halo = 0.5 * max(piece.width_mm, piece.height_mm)\n        idx = [i for i, (x, z) in enumerate(full)\n               if piece.global_x0_mm - halo <= x <= piece.global_x1_mm + halo\n               and piece.global_z0_mm - halo <= z <= piece.global_z1_mm + halo]\n        a = max(0, min(idx) - 2)\n        b = min(len(full), max(idx) + 3)\n        return {"curve": _resample_polyline2(full[a:b], 1.0), "advance": "curve"}\n    first = base["main_a_local"][0]\n    rec = next(r for r in base["main_a_curves"]\n               if r["wave"] == first["wave"] and r["family"] == first["family"])\n    pts = [(float(x), float(z)) for x, z in rec["points"]]\n    pc = (0.5 * (piece.global_x0_mm + piece.global_x1_mm),\n          0.5 * (piece.global_z0_mm + piece.global_z1_mm))\n    si = min(range(len(pts)), key=lambda i: math.hypot(pts[i][0] - pc[0], pts[i][1] - pc[1]))\n    return {"curve": _trace_a_streamline_global(\n                pts[si][0], pts[si][1], _polyline_length2(pts[:si + 1]),\n                _polyline_length2(pts[si:]), A_TRACE_STEP_MM),\n            "advance": "seed", "seed": pts[si],\n            "negative": _polyline_length2(pts[:si + 1]),\n            "positive": _polyline_length2(pts[si:])}\n\n\ndef _advance_midpoint(point, distance):\n    if _mode_profile()["placement"] == "outer_to_inner":\n        return _waveset_advance_point_inward(point[0], point[1], distance)\n    return _advance_b_rise_global(point[0], point[1], distance, B_FRONT_MAX_STEP_MM)[0]\n\n\ndef _offset_road_curve(curve, tier, road_index):\n    if OPTICAL_MODE == "single-arc":\n        return list(curve)\n    out = []\n    for x, z in curve:\n        frame = mirror_frame_global(x, z)\n        profile = _stack_cross_section_profile(frame["facet_tilt_deg"])\n        centre = profile["tiers"][tier]["centres_u_mm"][road_index]\n        leading = max(profile["tiers"][0]["centres_u_mm"])\n        # Smooth reference curves are the leading base road.  Retain the old P\n        # origin convention so legacy P output is byte-for-byte unaffected.\n        offset = centre - leading if _mode_profile()["smooth"] else centre\n        out.append((x + frame["b_unit"][0] * offset,\n                    z + frame["b_unit"][1] * offset))\n    return out\n\n\ndef _clip_roads(curve, piece):\n    roads = {}\n    for tier, count in enumerate(_mode_profile()["tier_counts"]):\n        for road_index in range(count):\n            clips = _waveset_clip_curve(_offset_road_curve(curve, tier, road_index), piece)\n            roads[(tier, road_index)] = [\n                (p[0] - piece.global_x0_mm, p[1] - piece.global_z0_mm) for p in clips]\n    return roads\n\n\ndef _smooth_local_profile(center):\n    frame = mirror_frame_global(float(center[0]), float(center[1]))\n    support = _stack_cross_section_profile(frame["facet_tilt_deg"])\n    smooth = _smooth_cross_section_profile(frame["facet_tilt_deg"], support)\n    leading = smooth["leading_base_u_mm"]\n    return frame, support, smooth, {\n        "front_foot": smooth["front_foot_u_mm"] - leading,\n        "crest": smooth["crest_u_mm"] - leading,\n        "rear_foot": smooth["rear_foot_u_mm"] - leading,\n    }\n\n\ndef _smooth_assembly_extents(center):\n    frame, support, smooth, local = _smooth_local_profile(center)\n    leading = smooth["leading_base_u_mm"]\n    centres = [u - leading for tier in support["tiers"] for u in tier["centres_u_mm"]]\n    centres.extend(local.values())\n    radius = 0.5 * ARC_PROFILE_WIDTH_MM\n    return min(centres) - radius, max(centres) + radius\n\n\ndef _physical_envelope_gap(current, previous):\n    if not current:\n        return float("-inf")\n    if not _mode_profile()["smooth"]:\n        distances = [math.hypot(c[0] - p[0], c[1] - p[1]) for c, p in zip(current, previous)]\n        if OPTICAL_MODE == "single-arc":\n            return min(distances) - ARC_PROFILE_WIDTH_MM\n        gaps = []\n        for c, p, distance in zip(current, previous, distances):\n            dc = _du_for_frame(mirror_frame_global(c[0], c[1]))\n            dp = _du_for_frame(mirror_frame_global(p[0], p[1]))\n            for tier, count in enumerate(_mode_profile()["tier_counts"]):\n                gaps.append(distance + tier * dc - tier * dp - count * ARC_PROFILE_WIDTH_MM)\n        return min(gaps)\n    gaps = []\n    for near, far in zip(current, previous):\n        distance = math.hypot(near[0] - far[0], near[1] - far[1])\n        near_rear, _ = _smooth_assembly_extents(near)\n        _, far_front = _smooth_assembly_extents(far)\n        gaps.append(distance + near_rear - far_front)\n    return min(gaps)\n\n\ndef _smooth_front_samples(center, sample_count=None):\n    frame, support, smooth, local = _smooth_local_profile(center)\n    n = PROFILE_SAMPLE_COUNT if sample_count is None else max(3, int(sample_count))\n    out = []\n    for i in range(n):\n        fraction = i / (n - 1)\n        u = local["front_foot"] + (local["crest"] - local["front_foot"]) * fraction\n        height = (smooth["front_foot_height_mm"] +\n                  (smooth["crest_height_mm"] - smooth["front_foot_height_mm"]) * fraction)\n        x = float(center[0]) + frame["b_unit"][0] * u\n        z = float(center[1]) + frame["b_unit"][1] * u\n        ray = (MASTER_FAN.projector_x_mm - x,\n               MASTER_FAN.projector_z_mm - z,\n               MASTER_FAN.projector_distance_mm - height)\n        distance = math.sqrt(sum(q * q for q in ray))\n        out.append({"point_mm": (x, z), "height_mm": height,\n                    "profile_fraction": fraction,\n                    "projector_unit": tuple(q / distance for q in ray),\n                    "projector_distance_mm": distance})\n    return out\n\n\ndef _smooth_peak_record(center):\n    frame, support, smooth, local = _smooth_local_profile(center)\n    return {"center_mm": (float(center[0]) + frame["b_unit"][0] * local["crest"],\n                           float(center[1]) + frame["b_unit"][1] * local["crest"],\n                           smooth["crest_height_mm"]),\n            "frame": frame}\n\n\ndef _ray_margin_against_smoothing_peak(sample, blocker_center, prepared=None):\n    peak = _smooth_peak_record(blocker_center) if prepared is None else prepared\n    px, pz, ph_top = peak["center_mm"]\n    bx, bz = peak["frame"]["b_unit"]\n    x, z = sample["point_mm"]\n    rx, rz, rh = sample["projector_unit"]\n    # The deposited smoothing bead occupies the upper half of an ellipse whose\n    # top is the emitted XYZ path and whose base is one smooth layer below it.\n    base_h = ph_top - SMOOTH_LAYER_HEIGHT_MM\n    q0 = (x - px) * bx + (z - pz) * bz\n    dq = rx * bx + rz * bz\n    v0 = sample["height_mm"] - base_h\n    a = 0.5 * ARC_PROFILE_WIDTH_MM\n    b = SMOOTH_LAYER_HEIGHT_MM\n    lo = max(0.0, (base_h - sample["height_mm"]) / rh)\n    hi = min(sample["projector_distance_mm"], (ph_top - sample["height_mm"]) / rh)\n    if hi < lo - 1e-12:\n        return float("inf")\n    aa = (dq / a) ** 2 + (rh / b) ** 2\n    bb = 2.0 * (q0 * dq / (a * a) + v0 * rh / (b * b))\n    cc = (q0 / a) ** 2 + (v0 / b) ** 2 - 1.0\n    t = max(lo, min(hi, -bb / (2.0 * aa)))\n    return aa * t * t + bb * t + cc\n\n\ndef _pair_metrics(current, previous, piece, stride=1, profile_sample_count=None):\n    if not _mode_profile()["smooth"]:\n        if len(current) != len(previous):\n            raise RuntimeError("v1.154: corresponding traces differ")\n        halo = ROAD_WIDTH_MM\n        eligible = [i for i, point in enumerate(current)\n                    if piece.global_x0_mm - halo <= point[0] <= piece.global_x1_mm + halo\n                    and piece.global_z0_mm - halo <= point[1] <= piece.global_z1_mm + halo]\n        idxs = ([eligible[len(eligible) // 2]] if OPTICAL_MODE in ("pyramid-3-2-1", "pyramid-2-1") and eligible\n                else [i for i in eligible if i % max(1, int(stride)) == 0])\n        if not idxs:\n            return None\n        physical = _physical_envelope_gap([current[i] for i in idxs], [previous[i] for i in idxs])\n        required = _required_visible_profile_fractions(profile_sample_count)\n        margins, critical = [], []\n        if required:\n            threshold = required[0]\n            for i in idxs:\n                visible, blocker = ((current[i], previous[i]) if OPTICAL_MODE == "single-arc"\n                                    else (previous[i], current[i]))\n                samples = [s for s in _profile_samples(visible, profile_sample_count)\n                           if s["profile_fraction"] >= threshold - 1e-12]\n                prepared = _previous_roads(blocker)\n                values = [(_ray_margin_against_stack(s, blocker, prepared), s["profile_fraction"])\n                          for s in samples]\n                margin, fraction = min(values, key=lambda q: q[0])\n                margins.append(margin); critical.append(fraction)\n        clear = min(margins) if margins else float("inf")\n        return {"physical_gap_min_mm": physical, "visibility_margin_min": clear,\n                "visibility_clear": not margins or clear >= RAY_NUMERICAL_MARGIN,\n                "critical_profile_fraction": min(critical) if critical else None,\n                "sample_count": len(idxs),\n                "profile_sample_count": profile_sample_count or PROFILE_SAMPLE_COUNT}\n\n    eligible = [i for i, point in enumerate(current)\n                if piece.global_x0_mm - ROAD_WIDTH_MM <= point[0] <= piece.global_x1_mm + ROAD_WIDTH_MM\n                and piece.global_z0_mm - ROAD_WIDTH_MM <= point[1] <= piece.global_z1_mm + ROAD_WIDTH_MM]\n    if not eligible:\n        return None\n    idxs = [eligible[len(eligible) // 2]]\n    physical = _physical_envelope_gap([current[i] for i in idxs], [previous[i] for i in idxs])\n    required = _required_visible_profile_fractions(profile_sample_count)\n    margins, critical = [], []\n    if required:\n        threshold = required[0]\n        for i in idxs:\n            visible, blocker = previous[i], current[i]\n            samples = [s for s in _smooth_front_samples(visible, profile_sample_count)\n                       if s["profile_fraction"] >= threshold - 1e-12]\n            peak = _smooth_peak_record(blocker)\n            values = [(_ray_margin_against_smoothing_peak(s, blocker, peak), s["profile_fraction"])\n                      for s in samples]\n            margin, fraction = min(values, key=lambda q: q[0])\n            margins.append(margin); critical.append(fraction)\n    clear = min(margins) if margins else float("inf")\n    return {"physical_gap_min_mm": physical, "visibility_margin_min": clear,\n            "visibility_clear": not margins or clear >= RAY_NUMERICAL_MARGIN,\n            "critical_profile_fraction": min(critical) if critical else None,\n            "sample_count": len(idxs),\n            "profile_sample_count": profile_sample_count or PROFILE_SAMPLE_COUNT,\n            "shadow_blocker": "smoothing_peak"}\n\n\ndef get_optical_lattice(piece):\n    key = (piece.name, OPTICAL_MODE, LAYER_HEIGHT_MM, PHYSICAL_HEIGHT_SCALE,\n           VISIBILITY_PERCENT, SMOOTH_EMBED_DEPTH_MM if _mode_profile()["smooth"] else None,\n           SMOOTH_LAYER_HEIGHT_MM if _mode_profile()["smooth"] else None,\n           SMOOTH_REAR_MAX_EMBED_MM, SMOOTH_NOZZLE_FLAT_DIAMETER_MM, SMOOTH_MAX_NOZZLE_PENETRATION_MM)\n    if key not in _OPTICAL_LATTICE_CACHE:\n        _OPTICAL_LATTICE_CACHE[key] = generate_optical_lattice(piece)\n    return _OPTICAL_LATTICE_CACHE[key]\n\n\ndef optical_spacing_report(piece):\n    lattice = get_optical_lattice(piece)\n    guarded = [p for p in lattice["plans"] if p.get("next_metrics")]\n    records = [p["next_metrics"] for p in guarded]\n    pitches = [p["next_pitch_mm"] for p in guarded]\n    full_gaps = [p["next_full_arc_physical_gap_mm"] for p in guarded]\n    report = {"result": "PASS", "mode": OPTICAL_MODE,\n              "visibility_percent": VISIBILITY_PERCENT,\n              "layer_height_mm": LAYER_HEIGHT_MM,\n              "physical_height_scale": PHYSICAL_HEIGHT_SCALE,\n              "physical_layer_height_mm": PHYSICAL_LAYER_HEIGHT_MM,\n              "printable_stacks": len(lattice["printable"]),\n              "spacing_sample_policy": SPACING_SAMPLE_POLICY,\n              "pitch_mm": {"min": min(pitches), "mean": sum(pitches) / len(pitches),\n                           "max": max(pitches)},\n              "physical_gap_min_mm": min(full_gaps),\n              "midpoint_physical_gap_min_mm": min(r["physical_gap_min_mm"] for r in records),\n              "visibility_margin_min": min(r["visibility_margin_min"] for r in records),\n              "full_required_profile_clear": all(r["visibility_clear"] for r in records)}\n    report.update({"support_tier_counts": list(_mode_profile()["tier_counts"]),\n                   "support_height_mm": len(_mode_profile()["tier_counts"]) * PHYSICAL_LAYER_HEIGHT_MM})\n    if not _mode_profile()["smooth"]:\n        report["shadow_blocker"] = "support_road_envelopes"\n    if _mode_profile()["smooth"]:\n        report.update({"shadow_blocker": "smoothing_peak",\n                       "smooth_embed_depth_mm": SMOOTH_EMBED_DEPTH_MM,\n                       "smooth_layer_height_mm": SMOOTH_LAYER_HEIGHT_MM})\n    return report\n\n\ndef _polyline_point_at_fraction(points, fraction):\n    if not points:\n        raise ValueError("empty curve")\n    f = max(0.0, min(1.0, float(fraction)))\n    lengths = [0.0]\n    for a, b in zip(points, points[1:]):\n        lengths.append(lengths[-1] + math.hypot(b[0] - a[0], b[1] - a[1]))\n    target = lengths[-1] * f\n    for i in range(len(points) - 1):\n        if target <= lengths[i + 1] + 1e-12:\n            span = max(lengths[i + 1] - lengths[i], 1e-12)\n            t = (target - lengths[i]) / span\n            return (points[i][0] + (points[i + 1][0] - points[i][0]) * t,\n                    points[i][1] + (points[i + 1][1] - points[i][1]) * t)\n    return tuple(points[-1])\n\n\ndef _bisect_radial_fractions(fractions):\n    vals = tuple(float(v) for v in fractions)\n    if len(vals) < 2:\n        return vals\n    out = []\n    for a, b in zip(vals, vals[1:]):\n        out.extend((a, 0.5 * (a + b)))\n    out.append(vals[-1])\n    return tuple(out)\n\n\ndef _smooth_vertices_for_plan(plan, fraction, piece):\n    center = _polyline_point_at_fraction(plan["curve"], fraction)\n    frame, support, smooth, local = _smooth_local_profile(center)\n    result = []\n    for kind, height_key in (("front_foot", "front_foot_height_mm"),\n                             ("crest", "crest_height_mm"),\n                             ("rear_foot", "rear_foot_height_mm")):\n        u = local[kind]\n        result.append({"x_mm": center[0] + frame["b_unit"][0] * u - piece.global_x0_mm,\n                       "y_mm": center[1] + frame["b_unit"][1] * u - piece.global_z0_mm,\n                       "height_mm": smooth[height_key], "kind": kind})\n    return result\n\n\ndef _smooth_fraction_gap(plan, fractions, piece):\n    feet = [_smooth_vertices_for_plan(plan, f, piece)[0] for f in fractions]\n    gaps = [math.hypot(b["x_mm"] - a["x_mm"], b["y_mm"] - a["y_mm"])\n            - ARC_PROFILE_WIDTH_MM for a, b in zip(feet, feet[1:])]\n    return max(gaps) if gaps else 0.0\n\n\ndef _build_smoothing_wave_sets(piece, lattice=None):\n    if not _mode_profile()["smooth"]:\n        return {"paths": [], "sets": [], "max_clear_gap_mm": 0.0}\n    lattice = get_optical_lattice(piece) if lattice is None else lattice\n    plans = list(reversed(lattice["printable"]))\n    seed_curve = plans[0]["curve"]\n    total = _polyline_length2(seed_curve)\n    seed_count = max(2, int(math.ceil(total / ARC_PROFILE_WIDTH_MM)) + 1)\n    fractions = tuple(i / (seed_count - 1) for i in range(seed_count))\n    births = {round(f, 14): 0 for f in fractions}\n    sets = [{"start_stack": 0, "fractions": fractions}]\n    max_gap = 0.0\n    for stack_index, plan in enumerate(plans):\n        while _smooth_fraction_gap(plan, fractions, piece) > ARC_PROFILE_WIDTH_MM + 1e-9:\n            old = set(round(f, 14) for f in fractions)\n            fractions = _bisect_radial_fractions(fractions)\n            for f in fractions:\n                if round(f, 14) not in old:\n                    births[round(f, 14)] = stack_index\n            sets.append({"start_stack": stack_index, "fractions": fractions})\n        max_gap = max(max_gap, _smooth_fraction_gap(plan, fractions, piece))\n    paths = []\n    for fraction in fractions:\n        start = births[round(fraction, 14)]\n        points = []\n        for plan in plans[start:]:\n            points.extend(_smooth_vertices_for_plan(plan, fraction, piece))\n        if points:\n            for chunk in _clip_smoothing_polyline(points, piece):\n                paths.append({"fraction": fraction, "start_stack": start, "points": chunk})\n    # Put complete cross-sections first.  Boundary-clipped fragments remain\n    # printable but do not obscure the primary geometry in audits/reports.\n    paths.sort(key=lambda path: (\n        not {"front_foot", "crest", "rear_foot"}.issubset(\n            {point["kind"] for point in path["points"]}),\n        path["fraction"], path["start_stack"]))\n    return {"paths": paths, "sets": sets, "max_clear_gap_mm": max_gap,\n            "initial_ray_count": seed_count, "final_ray_count": len(fractions)}\n\n\ndef _clip_segment_to_piece(a, b, piece):\n    """Liang-Barsky clip of one local XYZ smoothing segment."""\n    dx = b["x_mm"] - a["x_mm"]\n    dy = b["y_mm"] - a["y_mm"]\n    t0, t1 = 0.0, 1.0\n    for p, q in ((-dx, a["x_mm"]), (dx, piece.width_mm - a["x_mm"]),\n                 (-dy, a["y_mm"]), (dy, piece.height_mm - a["y_mm"])):\n        if abs(p) <= 1e-15:\n            if q < 0.0:\n                return None\n            continue\n        r = q / p\n        if p < 0.0:\n            if r > t1:\n                return None\n            t0 = max(t0, r)\n        else:\n            if r < t0:\n                return None\n            t1 = min(t1, r)\n    if t1 < t0:\n        return None\n    def at(t, original):\n        return {"x_mm": a["x_mm"] + dx * t,\n                "y_mm": a["y_mm"] + dy * t,\n                "height_mm": a["height_mm"] + (b["height_mm"] - a["height_mm"]) * t,\n                "kind": original if t <= 1e-12 or t >= 1.0 - 1e-12 else "boundary"}\n    return at(t0, a["kind"]), at(t1, b["kind"])\n\n\ndef _clip_smoothing_polyline(points, piece):\n    chunks, current = [], []\n    for a, b in zip(points, points[1:]):\n        clipped = _clip_segment_to_piece(a, b, piece)\n        if clipped is None:\n            if len(current) >= 2:\n                chunks.append(current)\n            current = []\n            continue\n        qa, qb = clipped\n        if not current or math.hypot(current[-1]["x_mm"] - qa["x_mm"],\n                                     current[-1]["y_mm"] - qa["y_mm"]) > 1e-8:\n            if len(current) >= 2:\n                chunks.append(current)\n            current = [qa]\n        if (math.hypot(current[-1]["x_mm"] - qb["x_mm"],\n                       current[-1]["y_mm"] - qb["y_mm"]) > 1e-10\n                or abs(current[-1]["height_mm"] - qb["height_mm"]) > 1e-10):\n            current.append(qb)\n    if len(current) >= 2:\n        chunks.append(current)\n    return chunks\n\n\ndef _gcode_xyz(point):\n    return (round(float(point[0]), 3), round(float(point[1]), 3), round(float(point[2]), 3))\n\n\ndef _smooth_segment_feed_mm_min(a, b):\n    """Feed for emitted XYZ coordinates at requested XY speed, capped in Z."""\n    ar, br = _gcode_xyz(a), _gcode_xyz(b)\n    xy = math.hypot(br[0]-ar[0], br[1]-ar[1])\n    dz = abs(br[2]-ar[2])\n    length = math.hypot(xy, dz)\n    duration = max(xy/SMOOTH_XY_SPEED_MM_S, dz/SMOOTH_Z_SPEED_LIMIT_MM_S)\n    if duration <= 0.0:\n        raise ValueError(\'zero-length smoothing speed segment\')\n    # Round down, so decimal G-code cannot request an axis above its limit.\n    return math.floor((60.0*length/duration)*100.0+1e-9)/100.0\n\n\ndef _gcode_distance3(a, b):\n    ar, br = _gcode_xyz(a), _gcode_xyz(b)\n    return math.sqrt(sum((y - x) ** 2 for x, y in zip(ar, br)))\n\n\ndef _explicit_mirror_wave_layer_gcode(piece, x_origin, y_origin):\n    lattice = get_optical_lattice(piece)\n    xo, yo = float(x_origin), float(y_origin)\n    counts = _mode_profile()["tier_counts"]\n    smooth_waves = _build_smoothing_wave_sets(piece, lattice) if _mode_profile()["smooth"] else None\n    max_smooth_height = (max((point["height_mm"] for path in smooth_waves["paths"]\n                              for point in path["points"]), default=0.0)\n                         if smooth_waves else 0.0)\n    support_top = len(counts) * PHYSICAL_LAYER_HEIGHT_MM\n    travel_z = BASE_TOP_Z_MM + max(support_top, max_smooth_height) + 0.160\n    rows = [f"; FC3D_V1154_OPTICAL_START mode={OPTICAL_MODE} visibility={VISIBILITY_PERCENT}% "\n            f"dose_height={LAYER_HEIGHT_MM:.3f} physical_height_scale={PHYSICAL_HEIGHT_SCALE:.3f} "\n            f"physical_layer_height={PHYSICAL_LAYER_HEIGHT_MM:.3f} stacks={len(lattice[\'printable\'])}",\n            f"; FC3D_V1154_VIEWER_TARGET x={MASTER_FAN.viewer_x_mm:.3f} "\n            f"eye_above_screen_bottom={MASTER_FAN.viewer_z_mm:.3f} distance={MASTER_FAN.viewer_distance_mm:.3f}",\n            f"; FC3D_V1154_SUPPORT_START tiers={len(counts)}"]\n    road_no = 0\n    for tier, count in enumerate(counts):\n        z_abs = BASE_TOP_Z_MM + (tier + 1) * PHYSICAL_LAYER_HEIGHT_MM\n        for stack_no, plan in enumerate(lattice["printable"], 1):\n            for road_index in range(count):\n                pts = [(xo + p[0], yo + p[1]) for p in plan["roads"][(tier, road_index)]]\n                total = _polyline_length2(pts)\n                dry = min(0.160, max(0.0, total * 0.45))\n                draw = max(0.0, total - dry)\n                if draw <= 1e-8:\n                    continue\n                draw_pts = _coalesce_curve_for_emission(_polyline_prefix_for_length(pts, draw))\n                road_no += 1\n                rows.append(f"; FC3D_V1154_SUPPORT_ROAD_START road={road_no} stack={stack_no} "\n                            f"tier={tier + 1} tier_road={road_index + 1} z={z_abs:.3f}")\n                rows.append(f"G0 Z{travel_z:.3f} F900 ; FC3D_V1154_SUPPORT_TRAVEL_Z")\n                rows.append(f"G0 X{pts[0][0]:.3f} Y{pts[0][1]:.3f} F18000 ; FC3D_V1154_SUPPORT_MOVE")\n                rows.append(f"G0 Z{z_abs:.3f} F900 ; FC3D_V1154_SUPPORT_HEIGHT")\n                rows.append("G1 E0.795 F1800 ; FC3D_V1154_SUPPORT_REPRIME")\n                for segment, (a, b) in enumerate(zip(draw_pts, draw_pts[1:])):\n                    distance = _gcode_chord_length(a, b)\n                    extrusion = distance * A_MAIN_E_PER_MM\n                    if round(extrusion, 5) > 0:\n                        rows.append(f"G1 X{b[0]:.3f} Y{b[1]:.3f} Z{z_abs:.3f} E{extrusion:.5f} "\n                                    f"F{A_PRINT_FEED_MM_S * 60:.0f} ; FC3D_V1154_SUPPORT_SEG "\n                                    f"road={road_no} seg={segment}")\n                rows.append("G1 E-0.800 F1800 ; FC3D_V1154_SUPPORT_RETRACT")\n                if dry > 1e-9:\n                    rows.append(f"G1 X{pts[-1][0]:.3f} Y{pts[-1][1]:.3f} Z{z_abs:.3f} F15000 "\n                                f"; FC3D_V1154_SUPPORT_DRY_TAIL len={dry:.3f}")\n                rows.append(f"; FC3D_V1154_SUPPORT_ROAD_END road={road_no}")\n    rows.append(f"; FC3D_V1154_SUPPORT_END roads={road_no}")\n\n    if _mode_profile()["smooth"]:\n        config = {"model":"half_ellipse_vertical", "front_embed_mm":SMOOTH_EMBED_DEPTH_MM,\n                  "smooth_height_mm":SMOOTH_LAYER_HEIGHT_MM,"rear_max_embed_mm":SMOOTH_REAR_MAX_EMBED_MM,\n                  "nozzle_flat_diameter_mm":SMOOTH_NOZZLE_FLAT_DIAMETER_MM,\n                  "max_nozzle_penetration_mm":SMOOTH_MAX_NOZZLE_PENETRATION_MM,\n                  "smooth_requested_xy_speed_mm_s":SMOOTH_XY_SPEED_MM_S,\n                  "smooth_z_speed_limit_mm_s":SMOOTH_Z_SPEED_LIMIT_MM_S,\n                  "speed_convention":"XY projection, Z capped; firmware controls acceleration"}\n        rows.append("; FC3D_V1154_SMOOTH_FIT_CONFIG "+json.dumps(config,sort_keys=True))\n    smooth_path_no = 0\n    if smooth_waves is not None:\n        rows.append(f"; FC3D_V1154_SMOOTH_START paths={len(smooth_waves[\'paths\'])} "\n                    f"sets={len(smooth_waves[\'sets\'])} xy_speed={SMOOTH_XY_SPEED_MM_S:g} z_speed_limit={SMOOTH_Z_SPEED_LIMIT_MM_S:g}")\n        for path in smooth_waves["paths"]:\n            points = path["points"]\n            if len(points) < 2:\n                continue\n            absolute = [(xo + point["x_mm"], yo + point["y_mm"],\n                         BASE_TOP_Z_MM + point["height_mm"]) for point in points]\n            smooth_path_no += 1\n            rows.append(f"; FC3D_V1154_SMOOTH_PATH_START path={smooth_path_no} "\n                        f"fraction={path[\'fraction\']:.9f} start_stack={path[\'start_stack\']}")\n            rows.append(f"G0 Z{travel_z:.3f} F900 ; FC3D_V1154_SMOOTH_TRAVEL_Z")\n            rows.append(f"G0 X{absolute[0][0]:.3f} Y{absolute[0][1]:.3f} F18000 ; FC3D_V1154_SMOOTH_MOVE")\n            rows.append(f"G0 Z{absolute[0][2]:.3f} F900 ; FC3D_V1154_SMOOTH_HEIGHT")\n            rows.append("G1 E0.795 F1800 ; FC3D_V1154_SMOOTH_REPRIME")\n            for segment, (a, b) in enumerate(zip(absolute, absolute[1:])):\n                distance = _gcode_distance3(a, b)\n                extrusion = distance * SMOOTH_E_PER_MM\n                if round(extrusion, 5) > 0:\n                    rows.append(f"G1 X{b[0]:.3f} Y{b[1]:.3f} Z{b[2]:.3f} E{extrusion:.5f} "\n                                f"F{_smooth_segment_feed_mm_min(a, b):.2f} ; FC3D_V1154_SMOOTH_SEG "\n                                f"path={smooth_path_no} seg={segment} kind={points[segment + 1][\'kind\']}")\n            rows.append("G1 E-0.800 F1800 ; FC3D_V1154_SMOOTH_RETRACT")\n            rows.append(f"; FC3D_V1154_SMOOTH_PATH_END path={smooth_path_no}")\n        rows.append(f"; FC3D_V1154_SMOOTH_END paths={smooth_path_no}")\n    rows.append(f"G0 Z{travel_z:.3f} F900 ; FC3D_V1154_OPTICAL_SAFE_END_Z")\n    rows.append(f"; FC3D_V1154_OPTICAL_END support_roads={road_no} smooth_paths={smooth_path_no}")\n    return rows\n\n\ndef audit_final_mirror_wave_paths(output):\n    with zipfile.ZipFile(output, "r") as archive:\n        gcode = archive.read("Metadata/plate_1.gcode").decode("utf-8")\n    block = gcode[gcode.find("FC3D_V1154_OPTICAL_START"):gcode.find("FC3D_V1154_OPTICAL_END")]\n    support = block.count("FC3D_V1154_SUPPORT_ROAD_START")\n    if not support or support != block.count("FC3D_V1154_SUPPORT_REPRIME") \\\n            or support != block.count("FC3D_V1154_SUPPORT_RETRACT") \\\n            or support != block.count("FC3D_V1154_SUPPORT_ROAD_END"):\n        raise RuntimeError("v1.154: support pressure-cycle audit failed")\n    smooth = block.count("FC3D_V1154_SMOOTH_PATH_START")\n    if _mode_profile()["smooth"]:\n        if not smooth or smooth != block.count("FC3D_V1154_SMOOTH_REPRIME") \\\n                or smooth != block.count("FC3D_V1154_SMOOTH_RETRACT") \\\n                or smooth != block.count("FC3D_V1154_SMOOTH_PATH_END"):\n            raise RuntimeError("v1.154: smoothing pressure-cycle audit failed")\n    return {"mode": OPTICAL_MODE, "support_roads": support, "smooth_paths": smooth,\n            "visibility_percent": VISIBILITY_PERCENT, "layer_height_mm": LAYER_HEIGHT_MM,\n            "smooth_layer_height_mm": SMOOTH_LAYER_HEIGHT_MM if _mode_profile()["smooth"] else None}\n\n# v154 selective-white P3 experiment. Surface-area quadrature on the front\n# quarter of each leading white half-ellipse; rear and black roads never enter\n# the target denominator. Geometry remains an undeformed bead approximation.\n_WHITE_SAMPLE_CACHE={}\n\ndef _white_samples(center, count=128):\n    key=(tuple(center),count)\n    if key in _WHITE_SAMPLE_CACHE:return _WHITE_SAMPLE_CACHE[key]\n    cx,cz=center;frame=mirror_frame_global(cx,cz);profile=_stack_cross_section_profile(frame[\'facet_tilt_deg\'])\n    a=ARC_PROFILE_WIDTH_MM/2;h=PHYSICAL_LAYER_HEIGHT_MM;out=[]\n    for ti,tier in enumerate(profile[\'tiers\'][:2]):\n        if ti != 1:continue # v154: only middle leading road is white\n        u0=max(tier[\'centres_u_mm\']);base=tier[\'base_height_mm\']\n        for j in range(count):\n            phi=(j+.5)*math.pi/(2*count);co=math.cos(phi);si=math.sin(phi)\n            u=u0+a*co;z=base+h*si\n            # Remove physically buried pieces of the white surface, not pieces\n            # merely hidden from the projector or viewer.\n            buried=False\n            for oi,other in enumerate(profile[\'tiers\']):\n                for ri,uc in enumerate(other[\'centres_u_mm\']):\n                    if oi==ti and ri==len(tier[\'centres_u_mm\'])-1:continue\n                    dh=z-other[\'base_height_mm\']\n                    if 0<=dh<=h and ((u-uc)/a)**2+(dh/h)**2<1-1e-9:buried=True\n            if buried:continue\n            nx,nz=h*co,a*si;nm=math.hypot(nx,nz)\n            out.append(dict(tier=ti+1,point_mm=(cx+frame[\'b_unit\'][0]*u,cz+frame[\'b_unit\'][1]*u),height_mm=z,\n                normal=(frame[\'b_unit\'][0]*nx/nm,frame[\'b_unit\'][1]*nx/nm,nz/nm),\n                weight=math.hypot(a*si,h*co)*math.pi/(2*count)))\n    _WHITE_SAMPLE_CACHE[key]=out\n    return out\n\ndef _white_clear(sample, center, target):\n    frame,roads=_previous_roads(center);bx,bz=frame[\'b_unit\'];x,z=sample[\'point_mm\'];h0=sample[\'height_mm\']\n    rx,rz,rh=target[0]-x,target[1]-z,target[2]-h0;dist=math.sqrt(rx*rx+rz*rz+rh*rh);rx/=dist;rz/=dist;rh/=dist\n    if sum(a*b for a,b in zip(sample[\'normal\'],(rx,rz,rh)))<=0:return False\n    q0=(x-center[0])*bx+(z-center[1])*bz;dq=rx*bx+rz*bz\n    a=ARC_PROFILE_WIDTH_MM/2;b=PHYSICAL_LAYER_HEIGHT_MM\n    for uc,base in roads:\n        lo=max(1e-5,(base-h0)/rh);hi=min(dist,(base+b-h0)/rh)\n        if hi<=lo:continue\n        v0=h0-base;aa=(dq/a)**2+(rh/b)**2;bb=2*((q0-uc)*dq/a**2+v0*rh/b**2);cc=((q0-uc)/a)**2+(v0/b)**2-1\n        t=max(lo,min(hi,-bb/(2*aa)))\n        if aa*t*t+bb*t+cc < -1e-8:return False\n    return True\n\ndef _white_pair_visibility(visible,blocker,count=128,extra_blockers=()):\n    p=(MASTER_FAN.projector_x_mm,MASTER_FAN.projector_z_mm,MASTER_FAN.projector_distance_mm)\n    v=(MASTER_FAN.viewer_x_mm,MASTER_FAN.viewer_z_mm,MASTER_FAN.viewer_distance_mm)\n    sums={2:[0.,0.,0.,0.]}\n    centres=[visible,blocker]+list(extra_blockers)\n    for s in _white_samples(visible,count):\n        wp=all(_white_clear(s,c,p) for c in centres);wv=all(_white_clear(s,c,v) for c in centres)\n        a=sums[s[\'tier\']];w=s[\'weight\'];a[0]+=w;a[1]+=w*wp;a[2]+=w*wv;a[3]+=w*(wp and wv)\n    rows=[]\n    for ti,(w,lp,lv,lj) in sums.items():\n        if w<=0:raise ValueError(\'white leading row has no exposed front surface\')\n        rows.append(dict(tier=ti,projector_fraction=lp/w,viewer_fraction=lv/w,joint_fraction=lj/w))\n    return dict(rows=rows,projector_min=min(a[\'projector_fraction\'] for a in rows),viewer_min=min(a[\'viewer_fraction\'] for a in rows),joint_min=min(a[\'joint_fraction\'] for a in rows))\n\ndef _white_full_metrics(current,previous,piece,count=128):\n    eligible=[i for i,(c,p) in enumerate(zip(current,previous)) if\n        (piece.global_x0_mm<=p[0]<=piece.global_x1_mm and piece.global_z0_mm<=p[1]<=piece.global_z1_mm)]\n    if not eligible:return None\n    ids=sorted(set(eligible[round(j*(len(eligible)-1)/8)] for j in range(9)))\n    records=[_white_pair_visibility(previous[i],current[i],count) for i in ids]\n    return dict(projector_min=min(r[\'projector_min\'] for r in records),viewer_min=min(r[\'viewer_min\'] for r in records),joint_min=min(r[\'joint_min\'] for r in records))\n\ndef _pair_metrics(current,previous,piece,stride=1,profile_sample_count=None):\n    eligible=[i for i,p in enumerate(current) if piece.global_x0_mm-ROAD_WIDTH_MM<=p[0]<=piece.global_x1_mm+ROAD_WIDTH_MM and piece.global_z0_mm-ROAD_WIDTH_MM<=p[1]<=piece.global_z1_mm+ROAD_WIDTH_MM]\n    if not eligible:return None\n    i=eligible[len(eligible)//2];r=_white_pair_visibility(previous[i],current[i]);target=VISIBILITY_PERCENT/100\n    physical=_physical_envelope_gap([current[i]],[previous[i]])\n    margin=r[\'projector_min\']-target\n    return dict(physical_gap_min_mm=physical,visibility_margin_min=margin,visibility_clear=margin>=-1e-9,\n        critical_profile_fraction=None,sample_count=1,profile_sample_count=128,white_visibility=r)\n\n_white_original_report=optical_spacing_report\n\ndef optical_spacing_report(piece):\n    report=_white_original_report(piece);lat=get_optical_lattice(piece)\n    report[\'shadow_blocker\']=\'all support roads; target exposed white front rows only\'\n    report[\'spacing_sample_policy\']=\'midpoint solve plus nine positions along each adjacent arc pair\'\n    report[\'white_surface_target\']=\'middle leading white front quarter only; surface-arclength weighted\'\n    report[\'viewer_requirement\']=\'report viewer and joint visibility separately; target applies to projector illumination\'\n    report[\'white_visibility_minima\']={k:min(p[\'white_full_metrics\'][k] for p in lat[\'plans\'] if p.get(\'white_full_metrics\')) for k in (\'projector_min\',\'viewer_min\',\'joint_min\')}\n    return report\n\n_white_generate=generate_optical_lattice\n\ndef generate_optical_lattice(piece):\n    checks=[]\n    for fx in (0.,.5,1.):\n        for fy in (0.,.5,1.):\n            c=(piece.global_x0_mm+fx*piece.width_mm,piece.global_z0_mm+fy*piece.height_mm)\n            b=mirror_frame_global(*c)[\'b_unit\'];far=(c[0]+b[0]*100,c[1]+b[1]*100)\n            checks.append(_white_pair_visibility(c,far,1024))\n    available=min(c[\'projector_min\'] for c in checks)\n    if available+1e-9<VISIBILITY_PERCENT/100:\n        raise ValueError(f\'selective white: own-pyramid shading limits projector visibility to approximately {100*available:.1f}% on this card, below requested {VISIBILITY_PERCENT}%. More spacing cannot fix this. Choose a lower visibility target or change the physical height scale explicitly.\')\n    return _white_generate(piece)\n\n_white_pair_metrics_saved=_pair_metrics\n_white_generate_saved=generate_optical_lattice\n_white_report_saved=optical_spacing_report\n\ndef _profile_pair_metrics(current, previous, piece, stride=1, profile_sample_count=None):\n    if not _mode_profile()["smooth"]:\n        if len(current) != len(previous):\n            raise RuntimeError("v1.154: corresponding traces differ")\n        halo = ROAD_WIDTH_MM\n        eligible = [i for i, point in enumerate(current)\n                    if piece.global_x0_mm - halo <= point[0] <= piece.global_x1_mm + halo\n                    and piece.global_z0_mm - halo <= point[1] <= piece.global_z1_mm + halo]\n        idxs = ([eligible[len(eligible) // 2]] if OPTICAL_MODE in ("pyramid-3-2-1", "pyramid-2-1") and eligible\n                else [i for i in eligible if i % max(1, int(stride)) == 0])\n        if not idxs:\n            return None\n        physical = _physical_envelope_gap([current[i] for i in idxs], [previous[i] for i in idxs])\n        required = _required_visible_profile_fractions(profile_sample_count)\n        margins, critical = [], []\n        if required:\n            threshold = required[0]\n            for i in idxs:\n                visible, blocker = ((current[i], previous[i]) if OPTICAL_MODE == "single-arc"\n                                    else (previous[i], current[i]))\n                samples = [s for s in _profile_samples(visible, profile_sample_count)\n                           if s["profile_fraction"] >= threshold - 1e-12]\n                prepared = _previous_roads(blocker)\n                values = [(_ray_margin_against_stack(s, blocker, prepared), s["profile_fraction"])\n                          for s in samples]\n                margin, fraction = min(values, key=lambda q: q[0])\n                margins.append(margin); critical.append(fraction)\n        clear = min(margins) if margins else float("inf")\n        return {"physical_gap_min_mm": physical, "visibility_margin_min": clear,\n                "visibility_clear": not margins or clear >= RAY_NUMERICAL_MARGIN,\n                "critical_profile_fraction": min(critical) if critical else None,\n                "sample_count": len(idxs),\n                "profile_sample_count": profile_sample_count or PROFILE_SAMPLE_COUNT}\n\n    eligible = [i for i, point in enumerate(current)\n                if piece.global_x0_mm - ROAD_WIDTH_MM <= point[0] <= piece.global_x1_mm + ROAD_WIDTH_MM\n                and piece.global_z0_mm - ROAD_WIDTH_MM <= point[1] <= piece.global_z1_mm + ROAD_WIDTH_MM]\n    if not eligible:\n        return None\n    idxs = [eligible[len(eligible) // 2]]\n    physical = _physical_envelope_gap([current[i] for i in idxs], [previous[i] for i in idxs])\n    required = _required_visible_profile_fractions(profile_sample_count)\n    margins, critical = [], []\n    if required:\n        threshold = required[0]\n        for i in idxs:\n            visible, blocker = previous[i], current[i]\n            samples = [s for s in _smooth_front_samples(visible, profile_sample_count)\n                       if s["profile_fraction"] >= threshold - 1e-12]\n            peak = _smooth_peak_record(blocker)\n            values = [(_ray_margin_against_smoothing_peak(s, blocker, peak), s["profile_fraction"])\n                      for s in samples]\n            margin, fraction = min(values, key=lambda q: q[0])\n            margins.append(margin); critical.append(fraction)\n    clear = min(margins) if margins else float("inf")\n    return {"physical_gap_min_mm": physical, "visibility_margin_min": clear,\n            "visibility_clear": not margins or clear >= RAY_NUMERICAL_MARGIN,\n            "critical_profile_fraction": min(critical) if critical else None,\n            "sample_count": len(idxs),\n            "profile_sample_count": profile_sample_count or PROFILE_SAMPLE_COUNT,\n            "shadow_blocker": "smoothing_peak"}\n\ndef _profile_generate_lattice(piece):\n    setup=_reference_setup(piece); previous=setup["curve"]\n    plans=[]; seen=False\n    for slot in range(1000):\n        clipped=_clip_roads(previous,piece)\n        printable=all(len(v)>=2 for v in clipped.values())\n        if printable: seen=True\n        elif seen: break\n        plans.append({"slot":slot,"curve":previous,"roads":clipped,"printable":printable,\n                      "seed_pitch_mm":None if slot==0 else plans[-1]["next_pitch_mm"],"metrics":None})\n        previous_mid=_curve_midpoint_in_piece(previous,piece)\n        def candidate(distance, samples=None):\n            if samples is None:samples=PROFILE_SAMPLE_COUNT\n            current_mid=_advance_midpoint(previous_mid,distance)\n            return current_mid,_pair_metrics([current_mid],[previous_mid],piece,1,samples)\n        low=0.0; high=max(0.45,ARC_PROFILE_WIDTH_MM); finished=False\n        while True:\n            current_mid,metrics=candidate(high)\n            if metrics is None:\n                probe,_=_advance_candidate(previous,setup,high)\n                if not _waveset_clip_curve(probe,piece): finished=True; break\n            if metrics and metrics["physical_gap_min_mm"]>=0.0 and metrics["visibility_clear"]:\n                for _ in range(10):\n                    mid=0.5*(low+high); mc,mm=candidate(mid)\n                    if mm and mm["physical_gap_min_mm"]>=0.0 and mm["visibility_clear"]: high=mid\n                    else: low=mid\n                current_mid,metrics=candidate(high,samples=PROFILE_SAMPLE_COUNT)\n                if not (metrics and metrics["physical_gap_min_mm"]>=0.0 and metrics["visibility_clear"]):\n                    low=high; high*=1.02; continue\n                curve,seed=_advance_candidate(previous,setup,high)\n                full_gap=_full_arc_physical_gap(curve,previous,piece)\n                # Midpoint shadow spacing is allowed to grow, never to undercut\n                # the complete finite-road envelopes. Correct only real overlap.\n                for _ in range(6):\n                    if full_gap>=0.0: break\n                    high += -full_gap + 1.0e-9\n                    curve,seed=_advance_candidate(previous,setup,high)\n                    full_gap=_full_arc_physical_gap(curve,previous,piece)\n                else:\n                    raise RuntimeError(f"{piece.name}: v1.154 full-arc physical clearance did not converge")\n                if full_gap<0.0:\n                    raise RuntimeError(f"{piece.name}: v1.154 full-arc physical overlap {full_gap:.9f} mm")\n                current_mid,metrics=candidate(high,samples=PROFILE_SAMPLE_COUNT)\n                if not (metrics and metrics["physical_gap_min_mm"]>=0.0 and metrics["visibility_clear"]):\n                    raise RuntimeError(f"{piece.name}: v1.154 corrected pitch lost midpoint clearance")\n                plans[-1]["next_pitch_mm"]=high\n                plans[-1]["next_metrics"]=metrics\n                plans[-1]["next_full_arc_physical_gap_mm"]=full_gap\n                if setup["advance"]=="seed": setup["seed"]=seed\n                previous=curve\n                break\n            high*=1.15\n            if high>8.0: raise RuntimeError(f"{piece.name}: v1.154 spacing solve exceeded 8 mm")\n        if finished: break\n    else: raise RuntimeError(f"{piece.name}: v1.154 lattice exceeded 1000 slots")\n    printable=[p for p in plans if p["printable"]]\n    if len(printable)<2: raise RuntimeError(f"{piece.name}: too few printable optical stacks")\n    return {"piece":piece.name,"mode":OPTICAL_MODE,"visibility_percent":VISIBILITY_PERCENT,\n            "layer_height_mm":LAYER_HEIGHT_MM,"physical_height_scale":PHYSICAL_HEIGHT_SCALE,\n            "physical_layer_height_mm":PHYSICAL_LAYER_HEIGHT_MM,"plans":plans,"printable":printable}\n\ndef _profile_spacing_report(piece):\n    lattice = get_optical_lattice(piece)\n    guarded = [p for p in lattice["plans"] if p.get("next_metrics")]\n    records = [p["next_metrics"] for p in guarded]\n    pitches = [p["next_pitch_mm"] for p in guarded]\n    full_gaps = [p["next_full_arc_physical_gap_mm"] for p in guarded]\n    report = {"result": "PASS", "mode": OPTICAL_MODE,\n              "visibility_percent": VISIBILITY_PERCENT,\n              "layer_height_mm": LAYER_HEIGHT_MM,\n              "physical_height_scale": PHYSICAL_HEIGHT_SCALE,\n              "physical_layer_height_mm": PHYSICAL_LAYER_HEIGHT_MM,\n              "printable_stacks": len(lattice["printable"]),\n              "spacing_sample_policy": SPACING_SAMPLE_POLICY,\n              "pitch_mm": {"min": min(pitches), "mean": sum(pitches) / len(pitches),\n                           "max": max(pitches)},\n              "physical_gap_min_mm": min(full_gaps),\n              "midpoint_physical_gap_min_mm": min(r["physical_gap_min_mm"] for r in records),\n              "visibility_margin_min": min(r["visibility_margin_min"] for r in records),\n              "full_required_profile_clear": all(r["visibility_clear"] for r in records)}\n    report.update({"support_tier_counts": list(_mode_profile()["tier_counts"]),\n                   "support_height_mm": len(_mode_profile()["tier_counts"]) * PHYSICAL_LAYER_HEIGHT_MM})\n    if not _mode_profile()["smooth"]:\n        report["shadow_blocker"] = "support_road_envelopes"\n    if _mode_profile()["smooth"]:\n        report.update({"shadow_blocker": "smoothing_peak",\n                       "smooth_embed_depth_mm": SMOOTH_EMBED_DEPTH_MM,\n                       "smooth_layer_height_mm": SMOOTH_LAYER_HEIGHT_MM})\n    return report\n\ndef _profile_report_with_white(piece):\n    report=_profile_spacing_report(piece)\n    key=(piece.name,OPTICAL_MODE,LAYER_HEIGHT_MM,PHYSICAL_HEIGHT_SCALE,VISIBILITY_PERCENT)\n    if key not in _PROFILE_WHITE_REPORT_CACHE:\n        plans=get_optical_lattice(piece)[\'plans\']\n        values=[_white_full_metrics(b[\'curve\'],a[\'curve\'],piece,128) for a,b in zip(plans,plans[1:])]\n        values=[v for v in values if v is not None]\n        _PROFILE_WHITE_REPORT_CACHE[key]={k:min(v[k] for v in values) for k in (\'projector_min\',\'viewer_min\',\'joint_min\')}\n    report[\'white_visibility_minima\']=_PROFILE_WHITE_REPORT_CACHE[key]\n    report[\'spacing_model\']=\'profile\'\n    report[\'white_surface_target\']=\'diagnostic only; v154 optical profile controls spacing\'\n    report[\'viewer_requirement\']=\'viewer and white visibility reported, not spacing constraints\'\n    return report\n'

