def _ct_without_detours(g):
    return re.sub(r'^; FC3D_CT_DETOUR_BEGIN[^\n]*\n.*?^; FC3D_CT_DETOUR_END\n','',g,flags=re.M|re.S)

def _configure_white_pyramid(rt):
    rt.LABEL_GLYPHS['W']=('10001','10001','10001','10101','10101','10101','01010')
    rt.REAR_TEXT_LINES=(rt.REAR_TEXT_LINES[0],rt.REAR_TEXT_LINES[1].replace('P ',('KP ' if rt.SPACING_MODEL=='profile' else 'KW ')),rt.REAR_TEXT_LINES[2])
    rt.REAR_PARAMETER_TEXT=' | '.join(rt.REAR_TEXT_LINES)
    rt.LABEL_GLYPHS['K']=('10001','10010','10100','11000','10100','10010','10001')
    original=rt._explicit_mirror_wave_layer_gcode
    def emit(*args,**kwargs):
        g='\n'.join(original(*args,**kwargs))+'\n'
        pat=r'^; FC3D_V1154_SUPPORT_ROAD_START[^\n]*\n.*?^; FC3D_V1154_SUPPORT_ROAD_END[^\n]*\n'
        blocks=list(re.finditer(pat,g,re.M|re.S))
        def key(m):
            tier=int(re.search(r' tier=(\d+)',m[0])[1]);road=int(re.search(r'tier_road=(\d+)',m[0])[1])
            white=tier==2 and road==2
            return (tier, (int(white) if tier==1 else int(not white)),m.start())
        if not blocks:raise RuntimeError('selective white: no support road blocks')
        a,b=blocks[0].start(),blocks[-1].end()
        if ''.join(m[0] for m in blocks)!=g[a:b]:raise RuntimeError('support blocks are not contiguous')
        return (g[:a]+''.join(m[0] for m in sorted(blocks,key=key))+g[b:]).splitlines()
    rt._explicit_mirror_wave_layer_gcode=emit

def _ct_state(before):
    state={'X':None,'Y':None,'Z':None,'F':1800.,'accel':8000.,'fan':128.}
    last_e=None;last_e_line=''
    for l in before.splitlines():
        s=l.split(';')[0].strip()
        if re.match(r'G[01]\s',s):
            for k,v in re.findall(r'\b([XYZF])([-+\d.]+)',s):state[k]=float(v)
            if re.match(r'G1 E[-+\d.]+(?: F[-+\d.]+)?$',s):last_e=float(re.search(r'\bE([-+\d.]+)',s)[1]);last_e_line=l
        m=re.match(r'M204 S([-+\d.]+)',s)
        if m:state['accel']=float(m[1])
        m=re.match(r'M106 (?:P1 )?S([-+\d.]+)',s)
        if m:state['fan']=float(m[1])
    if last_e not in (-.4,-.8):raise RuntimeError('contrast detour entry retract is not known')
    state['debt']=.8 if 'A_ENTRY_EXTRA_RETRACT' in last_e_line else -last_e
    if any(state[k] is None for k in 'XYZ'):raise RuntimeError('contrast detour position unknown')
    return state

def _ct_detour(heights,state,change=None,safe_z=4.,maximum=1.):
    rows=['; FC3D_CT_DETOUR_BEGIN']
    debt=state['debt']
    if change is not None:
        rows+= [f'; FC3D_CT_CHANGE_BEGIN next_tool={change}',_ct_change_macro(change,maximum).strip(),
                f'G1 E{2-debt:.3f} F300 ; FC3D_CT_ADJUST_MACRO_RETRACT', '; FC3D_CT_CHANGE_END']
    for z in heights:
        dose=.03326 if abs(z-.2)<1e-8 else .01567
        rows += [f'; FC3D_CT_TOWER_BEGIN z={z:.3f}', 'G90','M83',f'G0 Z{safe_z:.3f} F900','G0 X8.000 Y40.000 F6000',
                 f'G0 Z{z:.3f} F900','M204 S500',f'G1 E{debt:.3f} F1800']
        for row in range(31):
            x=28. if row%2==0 else 8.;y=40.+row*.4
            rows.append(f'G1 X{x:.3f} Y{y:.3f} E{20*dose:.6f} F1800 ; FC3D_CT_TOWER_DRAW')
            if row<30:rows.append(f'G1 X{x:.3f} Y{y+.4:.3f} E{.4*dose:.6f} F1800 ; FC3D_CT_TOWER_DRAW')
        rows += [f'G1 E-{debt:.3f} F1800', '; FC3D_CT_TOWER_END']
    rows += [f'G0 Z{safe_z:.3f} F900',f'G0 X{state["X"]:.6f} Y{state["Y"]:.6f} F6000',f'G0 Z{state["Z"]:.6f} F900',
             f'M204 S{state["accel"]:g}',f'M106 P1 S{state["fan"]:g}',f'G1 F{state["F"]:g}','; FC3D_CT_DETOUR_END']
    return '\n'.join(rows)+'\n'

def _apply_contrast(output,rt):
    import xml.etree.ElementTree as ET
    with zipfile.ZipFile(output) as z:
        original=g=z.read('Metadata/plate_1.gcode').decode()
        project=json.loads(z.read('Metadata/project_settings.config'));plate=json.loads(z.read('Metadata/plate_1.json'))
        root=ET.fromstring(z.read('Metadata/slice_info.config'))
    schedule=_tower_schedule(rt);batches=schedule['batches']
    def detour(heights,state,change=None):
        return _ct_detour(heights,state,change,schedule['safe_z'],schedule['max_deposited_z'])
    layers=list(re.finditer(r'^; CHANGE_LAYER$',g,re.M));insertions=[]
    if len(layers)!=4:raise RuntimeError('contrast expected three base layers and optical stage')
    for boundary,heights in [(layers[1].start(),batches[0]),(layers[2].start(),batches[1])]:
        insertions.append((boundary,detour(heights,_ct_state(g[:boundary]))))
    boundary=g.index('; DIRECT_LAYER V4 physical=3 ')
    insertions.append((boundary,detour(batches[2],_ct_state(g[:boundary]))))
    for tier,road,heights,change in [(2,2,batches[3],1),(2,1,batches[5],0)]:
        if not heights and change is None:continue
        m=re.search(r'^; FC3D_V1154_SUPPORT_ROAD_START[^\n]* tier='+str(tier)+r' tier_road='+str(road)+r' ',g,re.M)
        if not m:raise RuntimeError('selective white: missing colour boundary')
        insertions.append((m.start(),detour(heights,_ct_state(g[:m.start()]),change)))
    for at,block in sorted(insertions,reverse=True):g=g[:at]+block+g[at:]
    if _ct_without_detours(g)!=original:raise RuntimeError('colour detours changed model paths')
    colours=['#000000','#FFFFFF']
    for key,value in list(project.items()):
        if isinstance(value,list) and len(value)==1 and (key.startswith('filament_') or key.startswith('nozzle_temperature') or key in ('temperature_vitrification','idle_temperature') or 'bed_temperature' in key):project[key]=value*2
    project.update(filament_colour=colours,filament_multi_colour=colours,filament_type=['PETG']*2,
        filament_settings_id=['Generic PETG @BBL A1M']*2,filament_ids=['GFG99']*2,
        filament_map=['1']*2,filament_map_2=['1']*2,filament_nozzle_map=['0']*2,physical_extruder_map=['0']*2,
        enable_prime_tower='1',prime_tower_width='20',wipe_tower_x=['8'],wipe_tower_y=['40'],
        flush_volumes_matrix=['0','300','200','0'],flush_multiplier=['1']*2,
        fc3d_colour_roles=['A1 black base, bottom tier, rear roads and top','A2 white middle leading road only'],
        change_filament_gcode='; FC3D contrast: two resolved changes are embedded in the executable G-code')
    for key in ('filament_colour','filament_multi_colour','filament_type','filament_settings_id','filament_ids','filament_map','filament_map_2','filament_nozzle_map','nozzle_temperature','nozzle_temperature_initial_layer','flush_volumes_matrix','flush_multiplier','enable_prime_tower','change_filament_gcode'):
        val=project[key];text=';'.join(val) if isinstance(val,list) else str(val)
        g=re.sub(r'^; '+re.escape(key)+r' = .*$',lambda _:f'; {key} = {text}',g,flags=re.M)
    plate.update(filament_colors=colours,filament_ids=[0,1],first_extruder=0)
    coords=[];x=y=None;used={0:0.,1:0.};tool=0
    model=g[g.index('; CHANGE_LAYER'):g.index('; V4_MODEL_END')]
    for l in model.splitlines():
        tm=re.match(r'T([012])\s*$',l)
        if tm:tool=int(tm[1])
        if not re.match(r'G[01]\s',l):continue
        v={k:float(a) for k,a in re.findall(r'\b([XYE])([-+\d.]+)',l)}
        old=(x,y);x=v.get('X',x);y=v.get('Y',y)
        if v.get('E',0)>0 and ('X' in v or 'Y' in v):
            used[tool]+=v['E']
            if ('SUPPORT_SEG' in l) and None not in old:coords.extend([old,(x,y)])
    bb=[min(x for x,y in coords)-.2,min(y for x,y in coords)-.2,max(x for x,y in coords)+.2,max(y for x,y in coords)+.2]
    if bb[0]<=28.2 or min(bb)<0 or max(bb)>180:raise RuntimeError('prime pad conflicts with model or bed')
    # Retain the larger inherited backplate footprint if present.
    inherited=plate.get('bbox_all',bb)
    for o in plate.get('bbox_objects',[]):
        if isinstance(o,dict):o['bbox']=bb;o['area']=(bb[2]-bb[0])*(bb[3]-bb[1])
    plate['bbox_all']=[min(7.8,bb[0],inherited[0]),min(39.8,bb[1],inherited[1]),max(28.2,bb[2],inherited[2]),max(52.2,bb[3],inherited[3])]
    pn=root.find('plate')
    for n in list(pn):
        if n.tag in ('filament','layer_filament_lists'):pn.remove(n)
    for tool,colour in enumerate(colours):ET.SubElement(pn,'filament',dict(id=str(tool+1),tray_info_idx='GFG99',type='PETG',color=colour,
        used_m=f'{used[tool]/1000:.5f}',used_g=f'{used[tool]*2.4053*1.27/1000:.5f}',group_id='0',nozzle_diameter='0.40',volume_type='Standard',used_for_object='true',used_for_support='false'))
    lists=ET.SubElement(pn,'layer_filament_lists')
    for tools,layers in [('0','0 2'),('0 1','3 3')]:ET.SubElement(lists,'layer_filament_list',dict(filament_list=tools,layer_ranges=layers))
    for key,value in dict(has_filament_switcher='true',filament_maps='1 1',fc3d_active_raw_tools='0,1',fc3d_active_filament_one_based='1,2').items():
        node=next((n for n in pn.findall('metadata') if n.get('key')==key),None)
        if node is None:node=ET.SubElement(pn,'metadata',dict(key=key))
        node.set('value',value)
    # Header material arrays must agree with Connect/3MF material identities.
    headers={
        'filament':'1,2','filament_density':'1.27,1.27','filament_diameter':'1.75,1.75',
        'total filament length [mm]':','.join(f'{used[i]:.5f}' for i in range(2)),
        'total filament volume [cm^3]':','.join(f'{used[i]*2.4053/1000:.5f}' for i in range(2)),
        'total filament weight [g]':','.join(f'{used[i]*2.4053*1.27/1000:.5f}' for i in range(2)),
        'max_z_height':f'{_tower_schedule(rt)["max_deposited_z"]:.3f}'}
    for key,value in headers.items():
        g,count=re.subn(r'^; '+re.escape(key)+r'\s*:.*$',lambda _:f'; {key}: {value}',g,flags=re.M)
        if count!=1:raise RuntimeError('contrast header field missing: '+key)
    b=g.encode();_replace_zip(output,{'Metadata/plate_1.gcode':b,'Metadata/plate_1.gcode.md5':(hashlib.md5(b).hexdigest()+'\n').encode(),
        'Metadata/project_settings.config':json.dumps(project,separators=(',',':')).encode(),
        'Metadata/plate_1.json':json.dumps(plate,separators=(',',':')).encode(),
        'Metadata/slice_info.config':ET.tostring(root,encoding='utf-8',xml_declaration=True),
        'Metadata/filament_sequence.json':json.dumps({'plate_1':{'nozzle_sequence':[0,0,0],'optimal_assignment':[0,0],'sequence':[1,2,1]}}).encode()})
    return _audit_contrast(output,rt)

def _audit_contrast(output,rt):
    with zipfile.ZipFile(output) as z:
        g=z.read('Metadata/plate_1.gcode').decode();p=json.loads(z.read('Metadata/plate_1.json'))
        seq=json.loads(z.read('Metadata/filament_sequence.json'))
    if p['filament_ids']!=[0,1] or p['first_extruder']!=0 or seq['plate_1']['sequence']!=[1,2,1]:raise RuntimeError('selective white material metadata failed')
    tool=None;model=False;detour=False;optical=False;tier=road=None;switches=[];counts={0:0,1:0};seen=set()
    for l in g.splitlines():
        if l=='; CHANGE_LAYER':model=True
        if l=='; V4_MODEL_END':break
        m=re.match(r'T(\d+)\s*$',l)
        if m and int(m[1])<255:
            tool=int(m[1])
            if model:switches.append(tool)
        if 'CT_DETOUR_BEGIN' in l:detour=True
        if 'CT_DETOUR_END' in l:detour=False;continue
        if 'OPTICAL_START' in l:optical=True
        if not model or detour:continue
        if 'SUPPORT_ROAD_START' in l:
            tier=int(re.search(r' tier=(\d+)',l)[1]);road=int(re.search(r'tier_road=(\d+)',l)[1])
        if 'SUPPORT_SEG' in l:
            expected=int(tier==2 and road==2)
            if tool!=expected:raise RuntimeError('white/black support ownership mismatch')
            counts[tool]+=1;seen.add((tier,road,tool))
        elif 'SMOOTH_SEG' in l:raise RuntimeError('unexpected smoothing pass')
        elif (not optical or 'TOP_VALLEY_FILL_DRAW' in l) and re.match(r'G[01] ',l) and re.search(r'\b[XY][-\d]',l) and re.search(r'\bE(?:0\.[0-9]*[1-9]|[1-9])',l):
            if tool!=0:raise RuntimeError('base/fill not black')
    if switches!=[1,0] or seen!={(1,1,0),(1,2,0),(1,3,0),(2,1,0),(2,2,1),(3,1,0)}:raise RuntimeError('selective white colour sequence failed')
    heights=[float(z) for z in re.findall(r'CT_TOWER_BEGIN z=([\d.]+)',g)]
    if heights!=[z for batch in _tower_schedule(rt)['batches'] for z in batch]:raise RuntimeError('tower height sequence failed')
    for block in re.findall(r'; FC3D_CT_DETOUR_BEGIN\n.*?; FC3D_CT_DETOUR_END',g,re.S):
        if 'CT_CHANGE_BEGIN' in block and not re.search(r'^M109 S255\b',block,re.M):raise RuntimeError('PETG heat wait missing')
    spacing=rt.optical_spacing_report(rt.CURRENT_PIECE)
    report=dict(status='PASS',printer='a1mini',materials={'A1':'black base/bottom/rear/top','A2':'white middle leading road only'},
        colour_changes=2,tower_heights_mm=heights,draw_segments=counts,spacing=spacing,spacing_model=rt.SPACING_MODEL,
        purge_mm3={'black_to_white':300,'white_to_black':200},
        limitation='Undeformed half-ellipse bead model; actual PETG flow, opacity and optical gain are unmeasured.')
    _replace_zip(output,{'Metadata/fc3d_selective_white_audit.json':json.dumps(report,indent=2).encode()})
    return report


def _configure_spacing(rt,model):
    if model not in ('profile','white'):raise ValueError('spacing model must be profile or white')
    rt.SPACING_MODEL=model
    rt._OPTICAL_LATTICE_CACHE.clear()
    rt._PROFILE_WHITE_REPORT_CACHE={}
    rt._pair_metrics=rt._profile_pair_metrics if model=='profile' else rt._white_pair_metrics_saved
    rt.generate_optical_lattice=rt._profile_generate_lattice if model=='profile' else rt._white_generate_saved
    rt.optical_spacing_report=rt._profile_report_with_white if model=='profile' else rt._white_report_saved

def _tower_schedule(rt):
    import math
    h=rt.PHYSICAL_LAYER_HEIGHT_MM;base=rt.BASE_TOP_Z_MM
    tiers=[round(base+i*h,3) for i in (1,2,3)]
    if not base<tiers[0]<tiers[1]<tiers[2]:raise ValueError('chosen tier spacing is below G-code Z resolution')
    batches=[[.2],[.3]];last=3
    def until(target):
        nonlocal last
        end=max(last,int(math.floor(target*10+1e-8)))
        rows=[round(i/10,1) for i in range(last+1,end+1)];last=end;return rows
    batches.append(until(tiers[0]))
    black_advance=until(tiers[1])
    last+=1;batches.append(black_advance+[round(last/10,1)]) # fresh white prime layer
    batches.append([])
    last+=1;batches.append([round(last/10,1)]) # fresh black prime layer
    maximum=max(tiers[-1],last/10)
    return dict(batches=batches,tiers=tiers,max_deposited_z=maximum,safe_z=max(4.,maximum+1.))

def _ct_change_macro(change,maximum):
    template=CHANGE_TO_WHITE if change==1 else CHANGE_TO_BLACK
    result,n=re.subn(r'^G1 Z[\d.]+ F(1200|3000)$',lambda m:f'G1 Z{maximum+3:.3f} F{m[1]}',template,flags=re.M)
    if n!=2:raise RuntimeError('colour change lift template changed unexpectedly')
    return result


def main():
    ap=argparse.ArgumentParser(description="FC3D v1.154 consolidated parameterised ALR test card",allow_abbrev=False)
    ap.add_argument("--source",type=Path,default=Path("3dprintv1.179.py"))
    ap.add_argument("--piece",choices=tuple(f"{c}-{r}" for c in range(1,6) for r in range(1,6)),required=True)
    ap.add_argument("--print-mode",choices=("single-arc","pyramid-3-2-1","pyramid-2-1","smooth1","smooth2","smooth3"),required=True)
    ap.add_argument("--visibility-percent",type=int,required=True)
    ap.add_argument("--layer-height-mm",type=float,required=True,help="material-dose height in mm")
    ap.add_argument("--physical-height-scale",type=float,default=1.0,help="physical Z separation divided by material-dose height")
    ap.add_argument("--smooth-embed-depth-mm",type=float,default=0.02,help="maximum nominal vertical front-layer embedding into the support")
    ap.add_argument("--smooth-distance-mm",type=float,default=None,help=argparse.SUPPRESS)
    ap.add_argument("--smooth-rear-max-embed-mm",type=float,default=None,help="rear/valley embedding limit; defaults to smooth layer height")
    ap.add_argument("--smooth-nozzle-flat-diameter-mm",type=float,default=None,help="measured outside flat tip diameter for an optional contact estimate")
    ap.add_argument("--smooth-max-nozzle-penetration-mm",type=float,default=None,help="optional limit for the supplied flat nozzle footprint")
    ap.add_argument("--smooth-xy-speed-mm-s",type=float,default=30.0,help="smoothing extrusion XY speed only; default 30 mm/s, reduced as needed to keep Z at or below 30 mm/s")
    ap.add_argument("--smooth-layer-height-mm",type=float,default=0.10,help="smoothing Z height and material-dose height")
    ap.add_argument("--spacing-model",choices=("profile","white"),default="profile",help="profile: exact v145 spacing; white: middle white front-quarter illumination target")
    ap.add_argument("--printer-target",choices=("a1mini",),default="a1mini")
    ap.add_argument("--output",type=Path)
    ap.add_argument("--dry-validate",action="store_true")
    ap.add_argument("--slicer-target","--slicer",choices=("orca","studio"),default="orca")
    known,passthrough=ap.parse_known_args()
    if known.smooth_distance_mm is not None:
        ap.error("--smooth-distance-mm was replaced by --smooth-embed-depth-mm; the front-foot distance is now derived (example embedding: 0.02 mm)")
    _validate_options(known.print_mode,known.layer_height_mm,known.visibility_percent,known.physical_height_scale,known.smooth_embed_depth_mm,known.smooth_layer_height_mm,known.smooth_rear_max_embed_mm,known.smooth_nozzle_flat_diameter_mm,known.smooth_max_nozzle_penetration_mm,known.smooth_xy_speed_mm_s)
    if known.output is None: known.output=_default_output_name(known.print_mode,known.visibility_percent,known.layer_height_mm,known.physical_height_scale,known.smooth_embed_depth_mm,known.smooth_layer_height_mm,known.piece,known.smooth_xy_speed_mm_s)
    if known.print_mode != "pyramid-3-2-1":ap.error("selective white experiment requires pyramid-3-2-1")
    tag="KWKP" if known.spacing_model=="profile" else "KWKW"
    if "_P_" in known.output.name:known.output=known.output.with_name(known.output.name.replace("ALR_P_",f"ALR_{tag}_",1))
    rt=_load_runtime(known.print_mode,known.layer_height_mm,known.visibility_percent,known.physical_height_scale,known.smooth_embed_depth_mm,known.smooth_layer_height_mm,known.piece,known.smooth_rear_max_embed_mm,known.smooth_nozzle_flat_diameter_mm,known.smooth_max_nozzle_penetration_mm,known.smooth_xy_speed_mm_s)
    rt.reject_protected_passthrough(passthrough); rt.CURRENT_PIECE=rt.PieceSpec.for_name(known.piece); rt.RUNTIME_ORIGIN=None
    rt.set_runtime_e_per_mm(rt.STRUCTURAL_E_PER_MM)
    _configure_spacing(rt,known.spacing_model)
    _tower_schedule(rt)
    _configure_white_pyramid(rt)
    report=rt.optical_spacing_report(rt.CURRENT_PIECE)
    print(SCRIPT_VERSION)
    print("  print mode                     :",known.print_mode)
    print("  viewer eye above screen bottom :",f"{rt.MASTER_FAN.viewer_z_mm:.3f} mm")
    print("  viewer distance from screen    :",f"{rt.MASTER_FAN.viewer_distance_mm:.3f} mm")
    print("  material-dose height          :",f"{known.layer_height_mm:.3f} mm")
    print("  physical height scale           :",f"{known.physical_height_scale:.3f}")
    print("  physical layer separation       :",f"{rt.PHYSICAL_LAYER_HEIGHT_MM:.3f} mm")
    print("  required visible surface       :",f"{known.visibility_percent}% ({known.spacing_model} spacing model)")
    print("  spacing source                 : finite envelopes + requested projector visibility")
    print("  spacing sample policy          :",report["spacing_sample_policy"])
    print("  rear marking lines             :"," / ".join(rt.REAR_TEXT_LINES),"/ half-size arrow opposite v1.138 (group 180 deg)")
    print("  printable stacks               :",report["printable_stacks"])
    print("  dynamic pitch min/mean/max     :",f"{report['pitch_mm']['min']:.4f} / {report['pitch_mm']['mean']:.4f} / {report['pitch_mm']['max']:.4f} mm")
    if rt._mode_profile()["smooth"]:
        print("  smoothing requested XY speed   :",f"{rt.SMOOTH_XY_SPEED_MM_S:g} mm/s; Z capped at {rt.SMOOTH_Z_SPEED_LIMIT_MM_S:g} mm/s")
        print("  smoothing front embedding      :",f"{rt.SMOOTH_EMBED_DEPTH_MM:.3f} mm maximum (vertical model)")
        print("  smoothing rear embedding limit :",f"{rt.SMOOTH_REAR_MAX_EMBED_MM:.3f} mm")
        print("  nozzle flat contact model      :", "not evaluated: outside diameter not supplied" if rt.SMOOTH_NOZZLE_FLAT_DIAMETER_MM is None else f"{rt.SMOOTH_NOZZLE_FLAT_DIAMETER_MM:.3f} mm supplied flat diameter")
    if known.dry_validate:
        print("DRY V1.154 SIX-MODE VALIDATION: PASS"); return
    final_output=known.output
    package=final_output.with_name(final_output.name+".v154working.gcode.3mf")
    dp=rt.import_3dprint(known.source); rt.install_patches(dp,45.0,45.0,45.0)
    rt.SCRIPT_VERSION=SCRIPT_VERSION; rt.REAR_VERSION_TEXT=REAR_VERSION_TEXT
    rt.OPTICAL_MODE=known.print_mode; rt.LAYER_HEIGHT_MM=float(known.layer_height_mm); rt.PHYSICAL_HEIGHT_SCALE=float(known.physical_height_scale); rt.VISIBILITY_PERCENT=int(known.visibility_percent)
    _configure_smooth_runtime(rt,known.smooth_embed_depth_mm,known.smooth_layer_height_mm,known.smooth_rear_max_embed_mm,known.smooth_nozzle_flat_diameter_mm,known.smooth_max_nozzle_penetration_mm,known.smooth_xy_speed_mm_s)
    rt.REAR_TEXT_LINES=_rear_text_lines(known.print_mode,known.visibility_percent,known.layer_height_mm,known.physical_height_scale,known.smooth_embed_depth_mm,known.smooth_layer_height_mm,known.piece,known.smooth_xy_speed_mm_s)
    rt.REAR_PARAMETER_TEXT=" | ".join(rt.REAR_TEXT_LINES)
    exec(compile(OPTICAL_ENGINE_SOURCE,"<v154-consolidated-optical-engine>","exec"),rt.__dict__)
    rt.set_runtime_e_per_mm(rt.STRUCTURAL_E_PER_MM)
    _configure_spacing(rt,known.spacing_model)
    _tower_schedule(rt)
    _configure_white_pyramid(rt)
    with tempfile.TemporaryDirectory(prefix="fc3d_v154_") as td:
        from PIL import Image
        placeholder=Path(td)/"placeholder.png"; Image.new("RGB",(8,2),(22,22,22)).save(placeholder)
        base_args=[str(known.source),"--direct-layer-images",",".join([str(placeholder)]*rt.DIRECT_OPTICAL_LAYER_COUNT),"--direct-layout","4x2","--center-x","90.000","--center-y","90.000","--output",str(package),"--rp-pitch-mm",f"{rt.RP_PITCH_MM:.6f}","--print-width-mm",f"{rt.ROAD_WIDTH_MM:.6f}","--endpoint-trim-mm","0","--close-gaps-mm","0","--directional-block-mm","0","--edge-aa","off","--skip-absent-layer-materials","on","--progress","on","--filament-assignment-json",json.dumps({rt.LOGICAL_MATERIAL:rt.BLACK_ASSIGNMENT},separators=(",",":"))]
        old=sys.argv
        try: sys.argv=base_args+list(passthrough); dp.main()
        finally: sys.argv=old
    rt.apply_mirror_wave_paths(package)
    rt.apply_top_support_valley_fill(package)
    rt.apply_dynamic_tower_policy(package); rt.enforce_minimum_model_part_fan(package)
    rt.audit_final_base_interlock(package); rt.audit_final_black_texture_and_single_material(package)
    rt.audit_top_support_valley_fill(package)
    rt.convert_package_to_a1mini_orca(package); rt.normalize_a1mini_orca_reference_metadata(package); rt.apply_slicer_target_metadata(package,known.slicer_target)
    global CURRENT_PIECE_NAME,CURRENT_REAR_PARAMETER_TEXT
    CURRENT_PIECE_NAME=known.piece; CURRENT_REAR_PARAMETER_TEXT=rt.REAR_PARAMETER_TEXT
    if rt._mode_profile()["smooth"]:
        waves=rt._build_smoothing_wave_sets(rt.CURRENT_PIECE,rt.get_optical_lattice(rt.CURRENT_PIECE))
        smooth_max=max(point["height_mm"] for path in waves["paths"] for point in path["points"])
    else: smooth_max=0.0
    max_z=rt.BASE_TOP_Z_MM+max(len(rt._mode_profile()["tier_counts"])*rt.PHYSICAL_LAYER_HEIGHT_MM,smooth_max)
    _patch_native_lifecycle_and_revision(package,max_z)
    colour=_apply_contrast(package,rt)
    final=_audit_package(package,rt,known.piece)
    final["selective_white"]=colour
    if final["smoothing_contact"] is not None:
        _replace_zip(package,{"Metadata/fc3d_smoothing_contact_audit.json":json.dumps(final["smoothing_contact"],indent=2,allow_nan=False).encode("utf-8")})
    if rt._mode_profile()["smooth"]:
        speed_report={k:v for k,v in final.items() if 'speed' in k or k=='smooth_z_limited_segments'}
        speed_report['status']='PASS'
        speed_report['acceleration_status']='Firmware planned; no new acceleration commands'
        _replace_zip(package,{"Metadata/fc3d_smoothing_speed_audit.json":json.dumps(speed_report,indent=2,allow_nan=False).encode('utf-8')})
    package.replace(final_output)
    print("\nFINAL V1.154 AUDIT: PASS")
    for k,v in final.items(): print(f"  {k:28s} : {v}")
    print("Wrote",final_output)


